normal_texts:
Reactコンポーネントが毎回再レンダリングされる理由について、主な原因とその解決方法を説明します。

## 主な再レンダリングの原因

### 1. **stateの変更**
```jsx
function Counter() {
  const [count, setCount] = useState(0);

  // setCountが呼ばれるたびに再レンダリング
  return (
    <button onClick={() => setCount(count + 1)}>
      {count}
    </button>
  );
}
```

### 2. **propsの変更**
```jsx
// 親コンポーネント
function Parent() {
  const [value, setValue] = useState(0);

  return (
    <Child value={value} /> // valueが変わるとChildも再レンダリング
  );
}
```

### 3. **親コンポーネントの再レンダリング**
```jsx
function Parent() {
  const [count, setCount] = useState(0);

  return (
    <div>
      <button onClick={() => setCount(count + 1)}>Count: {count}</button>
      <Child /> {/* 親が再レンダリングされると子も再レンダリング */}
    </div>
  );
}
```

## よくある問題パターン

### 1. **関数の再生成**
```jsx
// ❌ 毎回新しい関数が作られる
function Parent() {
  const [count, setCount] = useState(0);

  const handleClick = () => {
    console.log('clicked');
  };

  return <Child onClick={handleClick} />; // 毎回異なる関数参照
}

// ✅ useCallbackで最適化
function Parent() {
  const [count, setCount] = useState(0);

  const handleClick = useCallback(() => {
    console.log('clicked');
  }, []); // 依存配列が変わらない限り同じ関数参照

  return <Child onClick={handleClick} />;
}
```

### 2. **オブジェクトの再生成**
```jsx
// ❌ 毎回新しいオブジェクトが作られる
function Parent() {
  const [name, setName] = useState('');

  const user = { name: name, id: 1 }; // 毎回新しいオブジェクト

  return <Child user={user} />;
}

// ✅ useMemoで最適化
function Parent() {
  const [name, setName] = useState('');

  const user = useMemo(() => ({
    name: name,
    id: 1
  }), [name]); // nameが変わった時だけ新しいオブジェクト

  return <Child user={user} />;
}
```

### 3. **インライン関数・オブジェクト**
```jsx
// ❌ 毎回新しい参照が作られる
function TodoList({ todos }) {
  return (
    <div>
      {todos.map(todo => (
        <TodoItem
          key={todo.id}
          todo={todo}
          onUpdate={() => updateTodo(todo.id)} // 毎回新しい関数
          style={{ color: 'blue' }} // 毎回新しいオブジェクト
        />
      ))}
    </div>
  );
}
```

## 解決方法

### 1. **React.memo**
```jsx
// 子コンポーネントをメモ化
const Child = React.memo(function Child({ value }) {
  console.log('Child rendered');
  return <div>{value}</div>;
});

// propsが同じなら再レンダリングをスキップ
```

### 2. **useCallback**
```jsx
function Parent() {
  const [count, setCount] = useState(0);
  const [name, setName] = useState('');

  // countが変わった時だけ関数を再生成
  const handleIncrement = useCallback(() => {
    setCount(c => c + 1);
  }, []);

  return <Child onIncrement={handleIncrement} />;
}
```

### 3. **useMemo**
```jsx
function ExpensiveComponent({ items }) {
  // itemsが変わった時だけ計算を実行
  const expensiveValue = useMemo(() => {
    return items.reduce((sum, item) => sum + item.value, 0);
  }, [items]);

  return <div>{expensiveValue}</div>;
}
```

### 4. **適切なkey属性**
```jsx
// ❌ indexをkeyに使う
{items.map((item, index) => (
  <Item key={index} data={item} />
))}

// ✅ 一意のIDをkeyに使う
{items.map(item => (
  <Item key={item.id} data={item} />
))}
```

## パフォーマンス分析ツール

```jsx
// React DevToolsのProfilerを使用
function App() {
  return (
    <Profiler id="App" onRender={onRenderCallback}>
      <Component />
    </Profiler>
  );
}

function onRenderCallback(id, phase, actualDuration) {
  console.log(`${id} took ${actualDuration}ms to render`);
}
```

適切な最適化により、不要な再レンダリングを防いでパフォーマンスを向上させることができます。

Reactコンポーネントが毎回再レンダリングされる主な原因について説明いたします。

## 主な再レンダリングの原因

### 1. **state（状態）の変更**
```jsx
function Counter() {
  const [count, setCount] = useState(0);

  // setCountが呼ばれるたびに再レンダリングが発生
  return (
    <button onClick={() => setCount(count + 1)}>
      {count}
    </button>
  );
}
```

### 2. **props（プロパティ）の変更**
```jsx
function Child({ name, age }) {
  return <div>{name} - {age}</div>;
}

function Parent() {
  const [count, setCount] = useState(0);

  return (
    <div>
      {/* Parentが再レンダリングされるとChildも再レンダリング */}
      <Child name="太郎" age={25} />
      <button onClick={() => setCount(count + 1)}>
        {count}
      </button>
    </div>
  );
}
```

### 3. **親コンポーネントの再レンダリング**
親が再レンダリングされると、デフォルトで子コンポーネントも再レンダリングされます。

### 4. **Context値の変更**
```jsx
const ThemeContext = createContext();

function App() {
  const [theme, setTheme] = useState('light');

  return (
    <ThemeContext.Provider value={theme}>
      {/* theme変更時、このProvider配下の全コンポーネントが再レンダリング */}
      <ComponentTree />
    </ThemeContext.Provider>
  );
}
```

## よくある不要な再レンダリングのパターン

### 1. **インライン関数の定義**
```jsx
// ❌ 毎回新しい関数オブジェクトが作成される
function Parent() {
  const [count, setCount] = useState(0);

  return (
    <Child onClick={() => console.log('clicked')} />
  );
}

// ✅ useCallbackで関数をメモ化
function Parent() {
  const [count, setCount] = useState(0);
  const handleClick = useCallback(() => {
    console.log('clicked');
  }, []);

  return <Child onClick={handleClick} />;
}
```

### 2. **インライン オブジェクト/配列**
```jsx
// ❌ 毎回新しいオブジェクトが作成される
function Parent() {
  return <Child style={{marginTop: 10}} />;
}

// ✅ オブジェクトを外部で定義
const style = {marginTop: 10};
function Parent() {
  return <Child style={style} />;
}
```

### 3. **不適切な依存配列**
```jsx
// ❌ countが変更されるたびに不要な計算
function Component() {
  const [count, setCount] = useState(0);
  const [name, setName] = useState('');

  const expensiveValue = useMemo(() => {
    return someExpensiveCalculation(name);
  }, [count, name]); // countは不要な依存

  return <div>{expensiveValue}</div>;
}
```

## 再レンダリングを最適化する方法

### 1. **React.memo**
```jsx
const Child = React.memo(function Child({ name }) {
  return <div>{name}</div>;
});
```

### 2. **useMemo**
```jsx
function Component({ items }) {
  const expensiveValue = useMemo(() => {
    return items.filter(item => item.active);
  }, [items]);

  return <div>{expensiveValue.length}</div>;
}
```

### 3. **useCallback**
```jsx
function Parent({ items }) {
  const [filter, setFilter] = useState('');

  const handleItemClick = useCallback((id) => {
    // アイテムクリック処理
  }, []);

  return (
    <div>
      {items.map(item => 
        <Item key={item.id} onClick={handleItemClick} />
      )}
    </div>
  );
}
```

### 4. **状態の分離**
```jsx
// ❌ カウンターとフォームが同じコンポーネント内
function App() {
  const [count, setCount] = useState(0);
  const [formData, setFormData] = useState({});

  return (
    <div>
      <Counter count={count} setCount={setCount} />
      <Form formData={formData} setFormData={setFormData} />
    </div>
  );
}

// ✅ 責任を分離
function App() {
  return (
    <div>
      <CounterComponent />
      <FormComponent />
    </div>
  );
}
```

## まとめ

Reactの再レンダリングは正常な動作ですが、不要な再レンダリングはパフォーマンスに影響します。適切なメモ化技法と状態管理により、効率的なアプリケーションを構築できます。

Reactコンポーネントが毎回再レンダリングされる主な原因と対策について説明いたします。

## 主な再レンダリングの原因

### 1. **propsの変更**
```jsx
// 親コンポーネントで新しいオブジェクトを毎回作成
function Parent() {
  return (
    <Child data={{ name: 'John' }} /> // 毎回新しいオブジェクト
  );
}
```

### 2. **stateの変更**
```jsx
function MyComponent() {
  const [count, setCount] = useState(0);

  // stateが変更されるたびに再レンダリング
  const handleClick = () => setCount(count + 1);

  return <button onClick={handleClick}>{count}</button>;
}
```

### 3. **親コンポーネントの再レンダリング**
```jsx
function Parent() {
  const [parentState, setParentState] = useState(0);

  return (
    <div>
      <button onClick={() => setParentState(parentState + 1)}>
        Parent: {parentState}
      </button>
      <Child /> {/* 親の再レンダリングで子も再レンダリング */}
    </div>
  );
}
```

## 対策方法

### 1. **React.memo()の使用**
```jsx
const Child = React.memo(({ name, age }) => {
  console.log('Child rendered');
  return <div>{name}: {age}</div>;
});

// propsが同じなら再レンダリングをスキップ
```

### 2. **useCallback()でコールバック関数を最適化**
```jsx
function Parent() {
  const [count, setCount] = useState(0);

  // 依存配列が変わらない限り同じ関数インスタンスを返す
  const handleClick = useCallback(() => {
    setCount(prev => prev + 1);
  }, []);

  return <Child onClick={handleClick} />;
}
```

### 3. **useMemo()で計算結果をメモ化**
```jsx
function ExpensiveComponent({ items, filter }) {
  const filteredItems = useMemo(() => {
    console.log('Filtering items...');
    return items.filter(item => item.type === filter);
  }, [items, filter]); // itemsかfilterが変わった時のみ再計算

  return (
    <ul>
      {filteredItems.map(item => <li key={item.id}>{item.name}</li>)}
    </ul>
  );
}
```

### 4. **参照の安定化**
```jsx
// ❌ 毎回新しいオブジェクトを作成
function BadParent() {
  return <Child config={{ theme: 'dark' }} />;
}

// ✅ オブジェクトを外部で定義
const config = { theme: 'dark' };
function GoodParent() {
  return <Child config={config} />;
}

// ✅ useMemoで安定化
function BetterParent() {
  const config = useMemo(() => ({ theme: 'dark' }), []);
  return <Child config={config} />;
}
```

## パフォーマンス最適化の例

```jsx
import React, { useState, useCallback, useMemo } from 'react';

const TodoList = React.memo(({ todos, onToggle, filter }) => {
  const filteredTodos = useMemo(() => {
    return todos.filter(todo => {
      if (filter === 'completed') return todo.completed;
      if (filter === 'active') return !todo.completed;
      return true;
    });
  }, [todos, filter]);

  return (
    <ul>
      {filteredTodos.map(todo => (
        <TodoItem
          key={todo.id}
          todo={todo}
          onToggle={onToggle}
        />
      ))}
    </ul>
  );
});

const TodoItem = React.memo(({ todo, onToggle }) => {
  const handleClick = useCallback(() => {
    onToggle(todo.id);
  }, [todo.id, onToggle]);

  return (
    <li onClick={handleClick} style={{ 
      textDecoration: todo.completed ? 'line-through' : 'none' 
    }}>
      {todo.text}
    </li>
  );
});
```

## 注意点

- **過度な最適化は避ける**: 全てのコンポーネントをmemo化する必要はありません
- **依存配列を正確に**: useCallback、useMemoの依存配列は適切に設定する
- **プロファイリング**: React DevToolsを使って実際のパフォーマンスを測定する

このような対策により、不要な再レンダリングを防いでアプリケーションのパフォーマンスを向上させることができます。

caveman_texts:
再レンダリング原因複数ある。主要パターン：

**状態変更**
```jsx
const [count, setCount] = useState(0);
// setCount呼び出し → 再レンダリング
```

**props変更**
```jsx
// 親コンポーネントで新しいオブジェクト作成
<Child data={{name: "test"}} /> // 毎回新しい参照 → 再レンダリング
```

**親再レンダリング**
```jsx
function Parent() {
  const [state, setState] = useState(0);
  return <Child />; // 親更新時、子も再レンダリング
}
```

**useEffect依存配列**
```jsx
useEffect(() => {
  // 何かの処理
}, [user]); // userオブジェクト変更時
```

**修正方法：**
- `React.memo()` - props同じなら再レンダリングスキップ
- `useMemo()` - 重い計算結果キャッシュ
- `useCallback()` - 関数参照固定
- 状態リフトアップ避ける

具体的エラー見せて。原因特定手伝う。

genshijin_texts:
inline object/function prop → 新参照 → 再レンダリング。

```jsx
// 悪い例
<Child style={{color: 'red'}} onClick={() => {}} />
// レンダリング毎 新obj/fn → Child再レンダリング

// 良い例  
const style = {color: 'red'};
const handleClick = () => {};
<Child style={style} onClick={handleClick} />
// または useMemo/useCallback
```

原因: JS オブジェクト比較 = 参照比較。内容同じでも参照違えば変化扱い。

対策: `useMemo` `useCallback` `React.memo`。

normal_texts:
認証ミドルウェアのトークン有効期限チェックのバグを修正いたします。よくあるバグパターンと修正方法をいくつか示しますね。

## よくあるバグパターンと修正例

### 1. 時刻比較の間違い

**バグのあるコード:**
```javascript
// 間違い：不等号の向きが逆
function isTokenExpired(token) {
    const now = Date.now();
    const expiry = token.exp * 1000; // JWTのexpは秒単位
    return now < expiry; // これは逆！
}
```

**修正版:**
```javascript
function isTokenExpired(token) {
    const now = Date.now();
    const expiry = token.exp * 1000; // JWTのexpは秒単位
    return now > expiry; // 現在時刻が有効期限を過ぎていればtrue
}
```

### 2. タイムゾーンとUTC時刻の混同

**バグのあるコード:**
```javascript
// 間違い：ローカル時刻とUTCが混在
function isTokenExpired(token) {
    const now = new Date().getTime(); // ローカル時刻
    const expiry = token.exp * 1000;  // UTC時刻
    return now > expiry;
}
```

**修正版:**
```javascript
function isTokenExpired(token) {
    const now = Date.now(); // UTC時刻
    const expiry = token.exp * 1000; // UTC時刻
    return now > expiry;
}
```

### 3. 完全な認証ミドルウェアの修正例

**修正されたミドルウェア:**
```javascript
const jwt = require('jsonwebtoken');

function authMiddleware(req, res, next) {
    try {
        // 1. トークンの取得
        const authHeader = req.headers.authorization;
        if (!authHeader || !authHeader.startsWith('Bearer ')) {
            return res.status(401).json({ error: 'トークンが提供されていません' });
        }

        const token = authHeader.substring(7); // "Bearer " を除去

        // 2. トークンの検証とデコード
        const decoded = jwt.verify(token, process.env.JWT_SECRET);

        // 3. 有効期限チェック（jwt.verifyで自動的に行われますが、明示的にチェック）
        if (isTokenExpired(decoded)) {
            return res.status(401).json({ error: 'トークンの有効期限が切れています' });
        }

        // 4. リクエストにユーザー情報を追加
        req.user = decoded;
        next();

    } catch (error) {
        if (error.name === 'TokenExpiredError') {
            return res.status(401).json({ error: 'トークンの有効期限が切れています' });
        } else if (error.name === 'JsonWebTokenError') {
            return res.status(401).json({ error: '無効なトークンです' });
        }

        console.error('認証エラー:', error);
        return res.status(500).json({ error: '認証処理でエラーが発生しました' });
    }
}

// 有効期限チェック関数
function isTokenExpired(decodedToken) {
    if (!decodedToken.exp) {
        return false; // 有効期限が設定されていない場合
    }

    const now = Math.floor(Date.now() / 1000); // 秒単位に変換
    const expiry = decodedToken.exp;

    return now >= expiry; // 現在時刻が有効期限以上ならtrue
}

module.exports = authMiddleware;
```

### 4. TypeScript版（型安全）

```typescript
import jwt from 'jsonwebtoken';
import { Request, Response, NextFunction } from 'express';

interface JWTPayload {
    userId: string;
    exp?: number;
    iat?: number;
}

interface AuthenticatedRequest extends Request {
    user?: JWTPayload;
}

export function authMiddleware(req: AuthenticatedRequest, res: Response, next: NextFunction): void {
    try {
        const authHeader = req.headers.authorization;

        if (!authHeader?.startsWith('Bearer ')) {
            res.status(401).json({ error: 'トークンが提供されていません' });
            return;
        }

        const token = authHeader.substring(7);
        const decoded = jwt.verify(token, process.env.JWT_SECRET!) as JWTPayload;

        // 明示的な有効期限チェック
        if (isTokenExpired(decoded)) {
            res.status(401).json({ error: 'トークンの有効期限が切れています' });
            return;
        }

        req.user = decoded;
        next();

    } catch (error) {
        if (error instanceof jwt.TokenExpiredError) {
            res.status(401).json({ error: 'トークンの有効期限が切れています' });
        } else if (error instanceof jwt.JsonWebTokenError) {
            res.status(401).json({ error: '無効なトークンです' });
        } else {
            console.error('認証エラー:', error);
            res.status(500).json({ error: '認証処理でエラーが発生しました' });
        }
    }
}

function isTokenExpired(payload: JWTPayload): boolean {
    if (!payload.exp) return false;

    const currentTime = Math.floor(Date.now() / 1000);
    return currentTime >= payload.exp;
}
```

## 主な修正点

1. **時刻比較の正確性**: `now >= expiry` で正しく判定
2. **単位の統一**: 秒単位で統一して比較
3. **エラーハンドリングの改善**: 適切な例外処理
4. **型安全性**: TypeScriptでの型定義
5. **セキュリティ**: 適切なエラーメッセージ

このような修正により、トークンの有効期限チェックが正確に動作するようになります。

認証ミドルウェアのトークン有効期限チェックのバグを修正いたします。一般的なバグのパターンと修正例を示します。

## よくあるバグのパターンと修正例

### 1. 時刻比較の間違い

**バグのあるコード例:**
```javascript
// 間違った例 - 時刻の比較が逆
function isTokenValid(token) {
    const currentTime = Math.floor(Date.now() / 1000);
    const expirationTime = token.exp;

    // バグ: 比較が逆になっている
    return currentTime > expirationTime;
}
```

**修正版:**
```javascript
function isTokenValid(token) {
    const currentTime = Math.floor(Date.now() / 1000);
    const expirationTime = token.exp;

    // 修正: 現在時刻が有効期限より前であることを確認
    return currentTime < expirationTime;
}
```

### 2. 完全な認証ミドルウェアの修正例

**修正版 (Node.js/Express):**
```javascript
const jwt = require('jsonwebtoken');

function authMiddleware(req, res, next) {
    try {
        // Authorizationヘッダーからトークンを取得
        const authHeader = req.headers.authorization;

        if (!authHeader) {
            return res.status(401).json({ error: 'Authorization header missing' });
        }

        const token = authHeader.startsWith('Bearer ') 
            ? authHeader.slice(7) 
            : authHeader;

        if (!token) {
            return res.status(401).json({ error: 'Token missing' });
        }

        // トークンをデコード（検証なし）して有効期限をチェック
        const decoded = jwt.decode(token);

        if (!decoded) {
            return res.status(401).json({ error: 'Invalid token format' });
        }

        // 有効期限チェック
        if (!isTokenValid(decoded)) {
            return res.status(401).json({ error: 'Token expired' });
        }

        // トークンの署名検証
        const verified = jwt.verify(token, process.env.JWT_SECRET);

        // リクエストオブジェクトにユーザー情報を追加
        req.user = verified;

        next();

    } catch (error) {
        if (error.name === 'TokenExpiredError') {
            return res.status(401).json({ error: 'Token expired' });
        } else if (error.name === 'JsonWebTokenError') {
            return res.status(401).json({ error: 'Invalid token' });
        }

        return res.status(500).json({ error: 'Internal server error' });
    }
}

function isTokenValid(token) {
    // 有効期限フィールドが存在しない場合
    if (!token.exp) {
        return false;
    }

    const currentTime = Math.floor(Date.now() / 1000);
    const expirationTime = token.exp;

    // 少しのバッファ時間を考慮（オプション）
    const CLOCK_TOLERANCE = 30; // 30秒

    // 修正: 正しい比較演算子を使用
    return currentTime < (expirationTime + CLOCK_TOLERANCE);
}

module.exports = authMiddleware;
```

### 3. Python (Flask) での修正例

```python
from functools import wraps
import jwt
from datetime import datetime, timezone
from flask import request, jsonify, current_app

def auth_required(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        try:
            # Authorizationヘッダーからトークンを取得
            auth_header = request.headers.get('Authorization')

            if not auth_header:
                return jsonify({'error': 'Authorization header missing'}), 401

            token = auth_header.replace('Bearer ', '') if auth_header.startswith('Bearer ') else auth_header

            if not token:
                return jsonify({'error': 'Token missing'}), 401

            # トークンをデコードして有効期限をチェック
            try:
                # まず署名検証なしでデコード
                decoded = jwt.decode(token, options={"verify_signature": False})

                # 有効期限チェック
                if not is_token_valid(decoded):
                    return jsonify({'error': 'Token expired'}), 401

                # 署名検証
                verified = jwt.decode(token, current_app.config['JWT_SECRET'], algorithms=['HS256'])

                # リクエストコンテキストにユーザー情報を追加
                request.user = verified

                return f(*args, **kwargs)

            except jwt.ExpiredSignatureError:
                return jsonify({'error': 'Token expired'}), 401
            except jwt.InvalidTokenError:
                return jsonify({'error': 'Invalid token'}), 401

        except Exception as e:
            return jsonify({'error': 'Internal server error'}), 500

    return decorated_function

def is_token_valid(token):
    """トークンの有効期限をチェック"""
    if 'exp' not in token:
        return False

    current_time = datetime.now(timezone.utc).timestamp()
    expiration_time = token['exp']

    # 修正: 正しい比較（現在時刻 < 有効期限）
    return current_time < expiration_time
```

## 主な修正ポイント

1. **比較演算子の修正**: `current_time < expiration_time` が正しい
2. **エラーハンドリングの改善**: 適切な例外処理を追加
3. **トークン形式の検証**: トークンが正しい形式かチェック
4. **有効期限フィールドの存在確認**: `exp`フィールドの有無をチェック
5. **時刻の正規化**: 同じ単位（秒）で比較

どの部分のバグを修正したいか、または使用している技術スタック（Node.js、Python、Java等）を教えていただければ、より具体的な修正案を提供できます。

認証ミドルウェアのトークン有効期限チェックのバグを修正いたします。よくある問題パターンと修正例をご紹介します。

## よくあるバグパターンと修正

### 1. 時刻比較の問題（JavaScript/Node.js例）

**バグのあるコード:**
```javascript
// ❌ バグのある例
function validateToken(token) {
  try {
    const decoded = jwt.verify(token, secret);
    const now = Date.now();
    const expiry = decoded.exp;

    // バグ: 単位が異なる（now はミリ秒、exp は秒）
    if (now > expiry) {
      return { valid: false, error: 'Token expired' };
    }

    return { valid: true, user: decoded };
  } catch (error) {
    return { valid: false, error: 'Invalid token' };
  }
}
```

**修正されたコード:**
```javascript
// ✅ 修正版
function validateToken(token) {
  try {
    const decoded = jwt.verify(token, secret);
    const now = Math.floor(Date.now() / 1000); // 秒単位に変換
    const expiry = decoded.exp;

    // 有効期限チェック
    if (now >= expiry) {
      return { valid: false, error: 'Token expired' };
    }

    // issued at チェック（未来のトークンを防ぐ）
    if (decoded.iat && now < decoded.iat) {
      return { valid: false, error: 'Token used before issued' };
    }

    return { valid: true, user: decoded };
  } catch (error) {
    if (error.name === 'TokenExpiredError') {
      return { valid: false, error: 'Token expired' };
    }
    return { valid: false, error: 'Invalid token' };
  }
}
```

### 2. Express.js ミドルウェアの完全な実装

```javascript
// ✅ 堅牢な認証ミドルウェア
const authMiddleware = (req, res, next) => {
  try {
    // トークン取得
    const authHeader = req.headers.authorization;
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      return res.status(401).json({ 
        error: 'Access token required' 
      });
    }

    const token = authHeader.substring(7);

    // トークン検証
    const decoded = jwt.verify(token, process.env.JWT_SECRET);

    // 追加の有効期限チェック
    const now = Math.floor(Date.now() / 1000);

    if (decoded.exp && now >= decoded.exp) {
      return res.status(401).json({ 
        error: 'Token expired' 
      });
    }

    if (decoded.iat && now < decoded.iat) {
      return res.status(401).json({ 
        error: 'Token not yet valid' 
      });
    }

    // ユーザー情報をリクエストに追加
    req.user = decoded;
    next();

  } catch (error) {
    if (error.name === 'TokenExpiredError') {
      return res.status(401).json({ 
        error: 'Token expired' 
      });
    } else if (error.name === 'JsonWebTokenError') {
      return res.status(401).json({ 
        error: 'Invalid token' 
      });
    } else {
      return res.status(500).json({ 
        error: 'Authentication error' 
      });
    }
  }
};
```

### 3. Python/Flask版の修正例

```python
# ✅ Python/Flask での修正版
import jwt
import time
from functools import wraps
from flask import request, jsonify, current_app

def token_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('Authorization')

        if not token:
            return jsonify({'error': 'Token is missing'}), 401

        try:
            if token.startswith('Bearer '):
                token = token[7:]

            # トークンをデコード
            data = jwt.decode(
                token, 
                current_app.config['SECRET_KEY'], 
                algorithms=['HS256']
            )

            # 手動での有効期限チェック（念のため）
            current_time = int(time.time())

            if 'exp' in data and current_time >= data['exp']:
                return jsonify({'error': 'Token has expired'}), 401

            if 'iat' in data and current_time < data['iat']:
                return jsonify({'error': 'Token not yet valid'}), 401

        except jwt.ExpiredSignatureError:
            return jsonify({'error': 'Token has expired'}), 401
        except jwt.InvalidTokenError:
            return jsonify({'error': 'Invalid token'}), 401
        except Exception as e:
            return jsonify({'error': 'Authentication error'}), 500

        return f(data, *args, **kwargs)
    return decorated
```

### 4. より堅牢なトークン管理

```javascript
// ✅ リフレッシュトークン機能付き
class TokenManager {
  static validateAccessToken(token) {
    try {
      const decoded = jwt.verify(token, process.env.JWT_ACCESS_SECRET);
      const now = Math.floor(Date.now() / 1000);

      // 有効期限チェック
      if (decoded.exp && now >= decoded.exp) {
        throw new Error('TOKEN_EXPIRED');
      }

      return { valid: true, user: decoded };
    } catch (error) {
      if (error.message === 'TOKEN_EXPIRED' || 
          error.name === 'TokenExpiredError') {
        return { valid: false, expired: true };
      }
      return { valid: false, expired: false };
    }
  }

  static async refreshTokenIfNeeded(accessToken, refreshToken) {
    const validation = this.validateAccessToken(accessToken);

    if (validation.valid) {
      return { accessToken, valid: true };
    }

    if (validation.expired && refreshToken) {
      try {
        // リフレッシュトークンで新しいアクセストークンを生成
        const refreshDecoded = jwt.verify(
          refreshToken, 
          process.env.JWT_REFRESH_SECRET
        );

        const newAccessToken = jwt.sign(
          { userId: refreshDecoded.userId },
          process.env.JWT_ACCESS_SECRET,
          { expiresIn: '15m' }
        );

        return { accessToken: newAccessToken, valid: true, refreshed: true };
      } catch (error) {
        return { valid: false, error: 'Refresh token invalid' };
      }
    }

    return { valid: false, error: 'Authentication required' };
  }
}
```

## 主な修正ポイント

1. **時刻の単位統一**: JWTのexpは秒単位、Date.now()はミリ秒単位
2. **適切なエラーハンドリング**: 期限切れと無効なトークンの区別
3. **iatチェック**: 未来のトークンを防ぐ
4. **セキュリティ向上**: リフレッシュトークン機能の追加

