require('dotenv').config();

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  // または
  // user: process.env.DB_USER,
  // password: process.env.DB_PASSWORD,
  // host: process.env.DB_HOST,
  // port: process.env.DB_PORT,
  // database: process.env.DB_NAME,

  max: 20,
  min: 5,
  idleTimeoutMillis: 30000,
  connectionTimeoutMillis: 5000,
});

module.exports = pool;
```

## 4. 基本的な使用方法

### database.js
```javascript
const pool = require('./pool');

// データベースクエリの実行
async function query(text, params) {
  const start = Date.now();
  try {
    const res = await pool.query(text, params);
    const duration = Date.now() - start;
    console.log('Executed query', { text, duration, rows: res.rowCount });
    return res;
  } catch (error) {
    console.error('Database query error:', error);
    throw error;
  }
}

// ユーザー取得の例
async function getUserById(id) {
  const result = await query('SELECT * FROM users WHERE id = $1', [id]);
  return result.rows[0];
}

// ユーザー作成の例
async function createUser(name, email) {
  const result = await query(
    'INSERT INTO users (name, email) VALUES ($1, $2) RETURNING *',
    [name, email]
  );
  return result.rows[0];
}

module.exports = {
  query,
  getUserById,
  createUser
};
```

## 5. トランザクションの使用

```javascript
const pool = require('./pool');

async function transferMoney(fromUserId, toUserId, amount) {
  const client = await pool.connect();

  try {
    await client.query('BEGIN');

    // 送金者の残高を減らす
    await client.query(
      'UPDATE accounts SET balance = balance - $1 WHERE user_id = $2',
      [amount, fromUserId]
    );

    // 受取人の残高を増やす
    await client.query(
      'UPDATE accounts SET balance = balance + $1 WHERE user_id = $2',
      [amount, toUserId]
    );

    await client.query('COMMIT');
    console.log('Transaction completed successfully');
  } catch (error) {
    await client.query('ROLLBACK');
    console.error('Transaction failed:', error);
    throw error;
  } finally {
    client.release(); // 重要：クライアントをプールに返却
  }
}
```

## 6. Express.jsでの使用例

```javascript
const express = require('express');
const { query, getUserById, createUser } = require('./database');

const app = express();
app.use(express.json());

// ユーザー一覧取得
app.get('/users', async (req, res) => {
  try {
    const result = await query('SELECT * FROM users');
    res.json(result.rows);
  } catch (error) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

// 特定ユーザー取得
app.get('/users/:id', async (req, res) => {
  try {
    const user = await getUserById(req.params.id);
    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }
    res.json(user);
  } catch (error) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ユーザー作成
app.post('/users', async (req, res) => {
  try {
    const { name, email } = req.body;
    const user = await createUser(name, email);
    res.status(201).json(user);
  } catch (error) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

## 7. エラーハンドリングと監視

```javascript
const pool = require('./pool');

// プールイベントの監視
pool.on('connect', (client) => {
  console.log('New client connected');
});

pool.on('remove', (client) => {
  console.log('Client removed from pool');
});

pool.on('error', (err, client) => {
  console.error('Unexpected error on idle client', err);
});

// グレースフルシャットダウン
process.on('SIGINT', async () => {
  console.log('Closing database pool...');
  await pool.end();
  process.exit(0);
});

process.on('SIGTERM', async () => {
  console.log('Closing database pool...');
  await pool.end();
  process.exit(0);
});
```

## 8. パフォーマンス監視

```javascript
const pool = require('./pool');

// プールの状態を監視する関数
function logPoolStatus() {
  console.log({
    totalCount: pool.totalCount,      // 総接続数
    idleCount: pool.idleCount,        // アイドル接続数
    waitingCount: pool.waitingCount   // 待機中のリクエスト数
  });
}

// 定期的にプールの状態をログ出力
setInterval(logPoolStatus, 10000); // 10秒ごと
```

## 重要なポイント

1. **接続数の調整**: アプリケーションの負荷に応じて`max`と`min`を適切に設定
2. **エラーハンドリング**: 必ずtry-catchでエラーを処理
3. **接続の解放**: トランザクション使用時は`client.release()`を忘れずに
4. **環境変数**: 機密情報は環境変数で管理
5. **モニタリング**: プールの状態を監視してパフォーマンスを最適化

