**現在のモード: 通常**

コールバック地獄 → async/await リファクタリング。

コード貼れ。

パターン:
```javascript
// Before: コールバック地獄
function getData(callback) {
  api1(data1 => {
    api2(data1, data2 => {
      api3(data2, data3 => {
        callback(data3);
      });
    });
  });
}

// After: async/await
async function getData() {
  const data1 = await api1();
  const data2 = await api2(data1);  
  const data3 = await api3(data2);
  return data3;
}
```

エラーハンドリング:
```javascript
// Before: 各レベル エラー処理
api1(data1 => {
  if (data1.error) return callback(data1.error);
  // ...
});

// After: try/catch
async function getData() {
  try {
    const data1 = await api1();
    const data2 = await api2(data1);
    return data2;
  } catch (error) {
    throw error;
  }
}
```

既存コード見せれば具体的変換可能。

コード貼れ。

具体的コールバック見せてもらえば、async/await変換手順示す。

一般パターン:
```js
// Before: コールバック地獄
getData(id, (err, data) => {
  if (err) return handleError(err);
  processData(data, (err, result) => {
    if (err) return handleError(err);
    saveResult(result, (err) => {
      if (err) return handleError(err);
      console.log('完了');
    });
  });
});

// After: async/await
async function handleData(id) {
  try {
    const data = await getData(id);
    const result = await processData(data);
    await saveResult(result);
    console.log('完了');
  } catch (err) {
    handleError(err);
  }
}
```

元コード貼って。具体的変換する。

コールバック地獄例:

```javascript
// 悪い例
getData(userId, function(err, user) {
  if (err) return handleError(err);
  getOrders(user.id, function(err, orders) {
    if (err) return handleError(err);
    getOrderDetails(orders[0].id, function(err, details) {
      if (err) return handleError(err);
      console.log(details);
    });
  });
});
```

async/await変換:

```javascript
// 良い例
async function fetchUserData(userId) {
  try {
    const user = await getData(userId);
    const orders = await getOrders(user.id);
    const details = await getOrderDetails(orders[0].id);
    console.log(details);
  } catch (err) {
    handleError(err);
  }
}
```

関数 Promise化 必要なら:

```javascript
// Promisify
const getData = (userId) => new Promise((resolve, reject) => {
  // 既存コールバック処理
});
```

直列処理 → `await`。並列処理 → `Promise.all()`。

normal_texts:
Expressルートのプルリクエストをセキュリティ観点でレビューする際の重要なポイントをご説明します。

## 主要なセキュリティチェック項目

### 1. 認証・認可の確認
```javascript
// ❌ 悪い例
app.get('/api/users/:id', (req, res) => {
  const user = getUserById(req.params.id);
  res.json(user);
});

// ✅ 良い例
app.get('/api/users/:id', authenticateToken, (req, res) => {
  // 認証済みユーザーのみアクセス可能
  if (req.user.id !== req.params.id && !req.user.isAdmin) {
    return res.status(403).json({ error: 'Forbidden' });
  }
  const user = getUserById(req.params.id);
  res.json(user);
});
```

### 2. 入力値検証
```javascript
// ❌ SQLインジェクションの脆弱性
app.get('/api/search', (req, res) => {
  const query = `SELECT * FROM products WHERE name LIKE '%${req.query.q}%'`;
  // 危険！
});

// ✅ 適切な入力値検証
const { body, validationResult } = require('express-validator');

app.post('/api/users', [
  body('email').isEmail().normalizeEmail(),
  body('password').isLength({ min: 8 }).matches(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)/),
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  // 処理続行
});
```

### 3. セキュリティヘッダーの設定
```javascript
const helmet = require('helmet');

app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
  }
}));
```

### 4. レート制限
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15分
  max: 100, // 最大100リクエスト
  message: 'Too many requests from this IP'
});

app.use('/api/', limiter);
```

### 5. エラーハンドリング
```javascript
// ❌ 情報漏洩の危険
app.get('/api/user/:id', (req, res) => {
  try {
    const user = database.query(`SELECT * FROM users WHERE id = ${req.params.id}`);
    res.json(user);
  } catch (error) {
    res.status(500).json({ error: error.message }); // 内部情報が漏洩
  }
});

// ✅ 安全なエラーハンドリング
app.get('/api/user/:id', (req, res) => {
  try {
    const user = getUserSafely(req.params.id);
    res.json(user);
  } catch (error) {
    logger.error('Database error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});
```

## レビュー時の具体的なチェックリスト

### 🔍 認証・認可
- [ ] すべての保護されるべきルートに認証ミドルウェアが適用されているか
- [ ] 適切な権限チェックが実装されているか
- [ ] JWTトークンの有効期限が適切に設定されているか

### 🔍 入力値検証
- [ ] すべてのユーザー入力に対して検証が行われているか
- [ ] SQLインジェクション対策が実装されているか
- [ ] XSS攻撃対策が実装されているか
- [ ] ファイルアップロードの検証が適切か

### 🔍 セキュリティ設定
- [ ] セキュリティヘッダーが適切に設定されているか
- [ ] CORS設定が適切か
- [ ] レート制限が実装されているか
- [ ] HTTPS強制が有効か

### 🔍 データ保護
- [ ] 機密情報がログに出力されていないか
- [ ] パスワードがハッシュ化されているか
- [ ] 個人情報の取り扱いが適切か

実際のPRコードを共有していただければ、より具体的なレビューコメントを提供できます。どの部分について特に懸念があるかお聞かせください。

Expressルートの Pull Request をセキュリティ観点でレビューする際のチェックポイントをご説明します。

## 🔒 主要なセキュリティチェックポイント

### 1. **認証・認可の確認**
```javascript
// ❌ 危険な例
app.get('/admin/users', (req, res) => {
  // 認証チェックなし
  res.json(getAllUsers());
});

// ✅ 安全な例
app.get('/admin/users', authenticateToken, authorize('admin'), (req, res) => {
  res.json(getAllUsers());
});
```

### 2. **入力値検証とサニタイゼーション**
```javascript
// ❌ 危険な例
app.post('/users', (req, res) => {
  const user = new User(req.body); // 直接使用
  user.save();
});

// ✅ 安全な例
app.post('/users', [
  body('email').isEmail().normalizeEmail(),
  body('name').trim().escape().isLength({min: 1, max: 100}),
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({errors: errors.array()});
  }
  // 処理続行
});
```

### 3. **SQLインジェクション対策**
```javascript
// ❌ 危険な例
app.get('/users/:id', (req, res) => {
  const query = `SELECT * FROM users WHERE id = ${req.params.id}`;
  db.query(query);
});

// ✅ 安全な例
app.get('/users/:id', (req, res) => {
  const query = 'SELECT * FROM users WHERE id = ?';
  db.query(query, [req.params.id]);
});
```

### 4. **レート制限の実装**
```javascript
// ✅ 推奨
const rateLimit = require('express-rate-limit');

const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15分
  max: 5, // 最大5回の試行
  message: 'ログイン試行回数が上限に達しました'
});

app.post('/login', loginLimiter, (req, res) => {
  // ログイン処理
});
```

## 📋 レビュー用チェックリスト

### **認証・認可**
- [ ] 保護が必要なルートに認証ミドルウェアが適用されているか
- [ ] 権限チェックが適切に実装されているか
- [ ] JWTトークンの検証が正しく行われているか

### **入力値検証**
- [ ] 全ての入力値が検証されているか
- [ ] パラメータの型チェックが行われているか
- [ ] XSS対策（エスケープ処理）が実装されているか
- [ ] ファイルアップロードの検証（サイズ、形式、パス）

### **データベースセキュリティ**
- [ ] パラメータ化クエリが使用されているか
- [ ] ORMを使用している場合、適切な設定か
- [ ] 機密情報がログに出力されていないか

### **エラーハンドリング**
```javascript
// ❌ 危険な例
app.get('/users/:id', (req, res) => {
  try {
    // 処理
  } catch (error) {
    res.status(500).json({error: error.message}); // 詳細なエラー情報を露出
  }
});

// ✅ 安全な例
app.get('/users/:id', (req, res) => {
  try {
    // 処理
  } catch (error) {
    console.error(error); // ログに記録
    res.status(500).json({error: 'Internal server error'}); // 一般的なメッセージ
  }
});
```

### **その他のセキュリティ要素**
- [ ] HTTPSの強制設定
- [ ] セキュリティヘッダーの設定（helmet.js）
- [ ] CORS設定の適切性
- [ ] セッション管理の安全性
- [ ] 機密情報のハードコーディング防止

## 🚨 よくある脆弱性パターン

1. **認証バイパス**
2. **権限昇格**
3. **情報漏洩**
4. **ディレクトリトラバーサル**
5. **ファイルアップロード脆弱性**

