ReactのError Boundaryの実装について説明します。

## Error Boundaryとは

Error Boundaryは、子コンポーネントツリー内でJavaScriptエラーをキャッチし、エラーをログに記録して、フォールバックUIを表示するReactコンポーネントです。

## クラスコンポーネントでの実装

```jsx
import React from 'react';

class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false, error: null, errorInfo: null };
  }

  static getDerivedStateFromError(error) {
    // 次のレンダリングでフォールバックUIを表示するために state を更新
    return { hasError: true };
  }

  componentDidCatch(error, errorInfo) {
    // エラーログの記録
    console.error('Error Boundary caught an error:', error, errorInfo);

    this.setState({
      error: error,
      errorInfo: errorInfo
    });

    // エラーレポートサービスに送信（例：Sentry）
    // logErrorToService(error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      // フォールバックUIをレンダリング
      return (
        <div className="error-boundary">
          <h2>🚨 エラーが発生しました</h2>
          <p>申し訳ございませんが、予期しないエラーが発生しました。</p>
          <details style={{ whiteSpace: 'pre-wrap' }}>
            <summary>エラー詳細（開発用）</summary>
            {this.state.error && this.state.error.toString()}
            <br />
            {this.state.errorInfo.componentStack}
          </details>
          <button 
            onClick={() => this.setState({ hasError: false, error: null, errorInfo: null })}
            className="retry-button"
          >
            再試行
          </button>
        </div>
      );
    }

    return this.props.children;
  }
}

export default ErrorBoundary;
```

## より高度なError Boundary

```jsx
import React from 'react';

class AdvancedErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      hasError: false,
      error: null,
      errorInfo: null,
      eventId: null
    };
  }

  static getDerivedStateFromError(error) {
    return { hasError: true };
  }

  componentDidCatch(error, errorInfo) {
    // エラーIDの生成
    const eventId = `error-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

    console.error('Error Boundary caught an error:', {
      error,
      errorInfo,
      eventId,
      timestamp: new Date().toISOString(),
      userAgent: navigator.userAgent,
      url: window.location.href
    });

    this.setState({
      error,
      errorInfo,
      eventId
    });

    // カスタムのonError コールバック
    if (this.props.onError) {
      this.props.onError(error, errorInfo, eventId);
    }
  }

  handleReset = () => {
    this.setState({
      hasError: false,
      error: null,
      errorInfo: null,
      eventId: null
    });

    if (this.props.onReset) {
      this.props.onReset();
    }
  };

  render() {
    if (this.state.hasError) {
      // カスタムフォールバックUIが提供されている場合
      if (this.props.fallback) {
        return this.props.fallback(
          this.state.error,
          this.state.errorInfo,
          this.handleReset
        );
      }

      // デフォルトのフォールバックUI
      return (
        <div className="error-boundary-container">
          <div className="error-boundary-content">
            <h1>🔧 システムエラー</h1>
            <p>アプリケーションでエラーが発生しました。</p>
            <p>エラーID: <code>{this.state.eventId}</code></p>

            <div className="error-actions">
              <button 
                onClick={this.handleReset}
                className="primary-button"
              >
                再試行
              </button>
              <button 
                onClick={() => window.location.reload()}
                className="secondary-button"
              >
                ページを再読み込み
              </button>
            </div>

            {process.env.NODE_ENV === 'development' && (
              <details className="error-details">
                <summary>開発者向け詳細情報</summary>
                <pre>
                  <strong>Error:</strong> {this.state.error?.toString()}
                  {'\n\n'}
                  <strong>Component Stack:</strong>
                  {this.state.errorInfo?.componentStack}
                </pre>
              </details>
            )}
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

export default AdvancedErrorBoundary;
```

## 使用方法

```jsx
import React from 'react';
import ErrorBoundary from './ErrorBoundary';
import MyComponent from './MyComponent';

function App() {
  return (
    <div>
      <h1>My React App</h1>

      {/* 特定のコンポーネントをError Boundaryで囲む */}
      <ErrorBoundary>
        <MyComponent />
      </ErrorBoundary>

      {/* カスタムフォールバックUIを使用 */}
      <ErrorBoundary
        fallback={(error, errorInfo, retry) => (
          <div>
            <h2>カスタムエラー画面</h2>
            <button onClick={retry}>もう一度試す</button>
          </div>
        )}
        onError={(error, errorInfo, eventId) => {
          // カスタムエラーハンドリング
          console.log('Custom error handler:', eventId);
        }}
      >
        <AnotherComponent />
      </ErrorBoundary>
    </div>
  );
}
```

## React Hooks版の代替実装

React HooksではError Boundaryを直接実装できませんが、カスタムフックで類似の機能を作成できます：

```jsx
import { useState, useEffect } from 'react';

// エラーハンドリング用のカスタムフック
export function useErrorHandler() {
  const [error, setError] = useState(null);

  const resetError = () => setError(null);

  const captureError = (error) => {
    console.error('Captured error:', error);
    setError(error);
  };

  // エラーが発生した場合の副作用
  useEffect(() => {
    if (error) {
      // エラーログの送信など
    }
  }, [error]);

  return {
    error,
    resetError,
    captureError,
    hasError: error !== null
  };
}

// 使用例
function MyComponent() {
  const { error, hasError, resetError, captureError } = useErrorHandler();

  const handleAsyncOperation = async () => {
    try {
      // 危険な処理
      await riskyOperation();
    } catch (err) {
      captureError(err);
    }
  };

  if (hasError) {
    return (
      <div>
        <h2>エラーが発生しました</h2>
        <button onClick={resetError}>再試行</button>
      </div>
    );
  }

  return (
    <div>
      <button onClick={handleAsyncOperation}>
        危険な処理を実行
      </button>
    </div>
  );
}
```

