```

### 2. より高機能なError Boundary

```jsx
import React, { Component } from 'react';

class AdvancedErrorBoundary extends Component {
  constructor(props) {
    super(props);
    this.state = { 
      hasError: false, 
      error: null, 
      errorInfo: null,
      eventId: null
    };
  }

  static getDerivedStateFromError(error) {
    return { hasError: true };
  }

  componentDidCatch(error, errorInfo) {
    this.setState({ error, errorInfo });

    // エラー報告の処理
    this.reportError(error, errorInfo);
  }

  reportError = async (error, errorInfo) => {
    // エラーIDの生成
    const eventId = Date.now().toString();
    this.setState({ eventId });

    try {
      // エラーログをサーバーに送信
      await fetch('/api/error-report', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          eventId,
          error: {
            message: error.message,
            stack: error.stack,
          },
          errorInfo,
          userAgent: navigator.userAgent,
          url: window.location.href,
          timestamp: new Date().toISOString(),
        }),
      });
    } catch (reportingError) {
      console.error('Failed to report error:', reportingError);
    }
  };

  handleReset = () => {
    this.setState({ 
      hasError: false, 
      error: null, 
      errorInfo: null,
      eventId: null 
    });
  };

  render() {
    if (this.state.hasError) {
      // カスタムフォールバックUIがある場合はそれを使用
      if (this.props.fallback) {
        return this.props.fallback(
          this.state.error,
          this.state.errorInfo,
          this.handleReset
        );
      }

      // デフォルトのエラーUI
      return (
        <div className="error-boundary">
          <div className="error-content">
            <h1>おっと、何か問題が発生しました</h1>
            <p>
              アプリケーションでエラーが発生しました。
              この問題は記録されており、調査中です。
            </p>

            <div className="error-actions">
              <button 
                onClick={this.handleReset}
                className="retry-button"
              >
                再試行
              </button>
              <button 
                onClick={() => window.location.href = '/'}
                className="home-button"
              >
                ホームに戻る
              </button>
            </div>

            {this.state.eventId && (
              <p className="error-id">
                エラーID: {this.state.eventId}
              </p>
            )}
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

export default AdvancedErrorBoundary;
```

### 3. React Hooksを使った補助コンポーネント

```jsx
import { useState, useEffect } from 'react';

// エラー境界の外側で使用するエラーハンドリングフック
export const useErrorHandler = () => {
  const [error, setError] = useState(null);

  useEffect(() => {
    if (error) {
      throw error;
    }
  }, [error]);

  const resetError = () => setError(null);
  const captureError = (error) => setError(error);

  return { captureError, resetError };
};

// 非同期エラーを処理するフック
export const useAsyncError = () => {
  const { captureError } = useErrorHandler();

  const catchAsync = (asyncFn) => {
    return async (...args) => {
      try {
        return await asyncFn(...args);
      } catch (error) {
        captureError(error);
      }
    };
  };

  return catchAsync;
};
```

## 使用方法

### 1. アプリケーション全体を包む

```jsx
import React from 'react';
import ReactDOM from 'react-dom';
import ErrorBoundary from './ErrorBoundary';
import App from './App';

ReactDOM.render(
  <ErrorBoundary>
    <App />
  </ErrorBoundary>,
  document.getElementById('root')
);
```

### 2. 特定のコンポーネントを包む

```jsx
import React from 'react';
import ErrorBoundary from './ErrorBoundary';
import UserDashboard from './UserDashboard';

function App() {
  return (
    <div className="app">
      <header>My App</header>

      <ErrorBoundary
        fallback={(error, errorInfo, reset) => (
          <div>
            <h3>ダッシュボードの読み込みに失敗しました</h3>
            <button onClick={reset}>再試行</button>
          </div>
        )}
      >
        <UserDashboard />
      </ErrorBoundary>
    </div>
  );
}
```

### 3. 非同期エラーの処理

```jsx
import React, { useState } from 'react';
import { useAsyncError } from './useErrorHandler';

function DataFetcher() {
  const [data, setData] = useState(null);
  const catchAsync = useAsyncError();

  const fetchData = catchAsync(async () => {
    const response = await fetch('/api/data');
    if (!response.ok) {
      throw new Error('データの取得に失敗しました');
    }
    const result = await response.json();
    setData(result);
  });

  return (
    <div>
      <button onClick={fetchData}>データを取得</button>
      {data && <div>{JSON.stringify(data)}</div>}
    </div>
  );
}
```

## 重要なポイント

1. **Error Boundaryはクラスコンポーネントでのみ実装可能**
2. **イベントハンドラー内のエラーはキャッチされない**
3. **非同期処理のエラーは別途処理が必要**
4. **開発環境と本番環境で表示内容を分ける**
5. **エラーログの適切な送信**

この実装により、Reactアプリケーションのエラー処理が大幅に改善されます。

ReactのError Boundaryの実装方法をご説明します。

## 基本的なError Boundaryの実装

### 1. クラスコンポーネントでの実装

```jsx
import React from 'react';

class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false, error: null, errorInfo: null };
  }

  static getDerivedStateFromError(error) {
    // エラーが発生したときに state を更新
    return { hasError: true };
