    // fetch('/api/errors', {
    //   method: 'POST',
    //   headers: { 'Content-Type': 'application/json' },
    //   body: JSON.stringify(errorData)
    // });
  };

  handleRetry = () => {
    this.setState({ 
      hasError: false, 
      error: null, 
      errorInfo: null 
    });
  };

  render() {
    if (this.state.hasError) {
      // カスタムのエラーUIを表示
      return (
        <div className="error-boundary">
          <div className="error-container">
            <h1>申し訳ございません</h1>
            <p>予期しないエラーが発生しました。</p>

            {process.env.NODE_ENV === 'development' && (
              <details className="error-details">
                <summary>開発者向け詳細情報</summary>
                <div className="error-info">
                  <h3>エラー:</h3>
                  <p>{this.state.error?.toString()}</p>

                  <h3>コンポーネントスタック:</h3>
                  <pre>{this.state.errorInfo?.componentStack}</pre>

                  <h3>スタックトレース:</h3>
                  <pre>{this.state.error?.stack}</pre>
                </div>
              </details>
            )}

            <div className="error-actions">
              <button onClick={this.handleRetry} className="retry-button">
                再試行
              </button>
              <button onClick={() => window.location.reload()} className="reload-button">
                ページをリロード
              </button>
            </div>
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

export default ErrorBoundary;
```

## 使用方法

### 1. アプリケーション全体をラップ

```jsx
import React from 'react';
import ReactDOM from 'react-dom/client';
import ErrorBoundary from './components/ErrorBoundary';
import App from './App';

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(
  <ErrorBoundary>
    <App />
  </ErrorBoundary>
);
```

### 2. 特定のコンポーネントをラップ

```jsx
import React from 'react';
import ErrorBoundary from './ErrorBoundary';
import ProblemComponent from './ProblemComponent';

function App() {
  return (
    <div>
      <h1>My App</h1>
      <ErrorBoundary>
        <ProblemComponent />
      </ErrorBoundary>

      {/* 他のコンポーネントには影響しない */}
      <div>他のコンテンツ</div>
    </div>
  );
}
```

## React 18+ でのより高度な実装

### react-error-boundaryライブラリを使用

```bash
npm install react-error-boundary
```

```jsx
import { ErrorBoundary, withErrorBoundary } from 'react-error-boundary';

// エラーフォールバックコンポーネント
function ErrorFallback({ error, resetErrorBoundary }) {
  return (
    <div role="alert" className="error-fallback">
      <h2>何かがうまくいきませんでした:</h2>
      <pre style={{ color: 'red' }}>{error.message}</pre>
      <button onClick={resetErrorBoundary}>再試行</button>
    </div>
  );
}

// 使用例1: コンポーネントとして
function App() {
  return (
    <ErrorBoundary
      FallbackComponent={ErrorFallback}
      onError={(error, errorInfo) => {
        console.log('Error logged:', error, errorInfo);
      }}
      onReset={() => {
        // エラーリセット時の処理
        window.location.reload();
      }}
    >
      <MyComponent />
    </ErrorBoundary>
  );
}

// 使用例2: HOCとして
const MyComponentWithErrorBoundary = withErrorBoundary(MyComponent, {
  FallbackComponent: ErrorFallback,
  onError: (error, errorInfo) => {
    console.log('Error logged:', error, errorInfo);
  }
});
```

## カスタムフックでエラーハンドリング

```jsx
import { useState, useCallback } from 'react';

export function useErrorHandler() {
  const [error, setError] = useState(null);

  const resetError = useCallback(() => {
    setError(null);
  }, []);

  const captureError = useCallback((error) => {
    setError(error);
  }, []);

  return { error, resetError, captureError };
}

// 使用例
function MyComponent() {
  const { error, resetError, captureError } = useErrorHandler();

  const handleAsyncOperation = async () => {
    try {
      // 何らかの非同期処理
      await riskyAsyncOperation();
    } catch (err) {
      captureError(err);
    }
  };

  if (error) {
    return (
      <div>
        <p>エラーが発生しました: {error.message}</p>
        <button onClick={resetError}>再試行</button>
      </div>
    );
  }

  return (
    <div>
      <button onClick={handleAsyncOperation}>
        危険な操作を実行
      </button>
    </div>
  );
}
```

