Nginxのリバースプロキシ設定について詳しく説明します。

## 基本的なリバースプロキシ設定

### 1. 基本的な設定例

```nginx
server {
    listen 80;
    server_name example.com;

    location / {
        proxy_pass http://127.0.0.1:3000;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }
}
```

### 2. よく使用されるプロキシヘッダー

```nginx
# クライアントの情報をバックエンドに転送
proxy_set_header Host $host;
proxy_set_header X-Real-IP $remote_addr;
proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
proxy_set_header X-Forwarded-Proto $scheme;
proxy_set_header X-Forwarded-Host $host;
proxy_set_header X-Forwarded-Port $server_port;
```

## 高度な設定オプション

### 3. タイムアウト設定

```nginx
server {
    listen 80;
    server_name example.com;

    location / {
        proxy_pass http://backend;

        # タイムアウト設定
        proxy_connect_timeout 30s;
        proxy_send_timeout 30s;
        proxy_read_timeout 30s;

        # バッファリング設定
        proxy_buffering on;
        proxy_buffer_size 4k;
        proxy_buffers 8 4k;
        proxy_busy_buffers_size 8k;
    }
}
```

### 4. アップストリーム（負荷分散）設定

```nginx
upstream backend {
    server 127.0.0.1:3000 weight=3;
    server 127.0.0.1:3001 weight=2;
    server 127.0.0.1:3002 weight=1;

    # ヘルスチェック（nginx plus）
    # health_check;
}

server {
    listen 80;
    server_name example.com;

    location / {
        proxy_pass http://backend;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    }
}
```

### 5. SSL/HTTPS設定

```nginx
server {
    listen 443 ssl http2;
    server_name example.com;

    ssl_certificate /path/to/certificate.crt;
    ssl_certificate_key /path/to/private.key;

    location / {
        proxy_pass http://127.0.0.1:3000;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto https;
    }
}

# HTTPからHTTPSへのリダイレクト
server {
    listen 80;
    server_name example.com;
    return 301 https://$server_name$request_uri;
}
```

## 特定のケース向け設定

### 6. WebSocket対応

```nginx
location /websocket {
    proxy_pass http://127.0.0.1:3000;
    proxy_http_version 1.1;
    proxy_set_header Upgrade $http_upgrade;
    proxy_set_header Connection "upgrade";
    proxy_set_header Host $host;
    proxy_set_header X-Real-IP $remote_addr;
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
}
```

### 7. 静的ファイルとAPIの分離

```nginx
server {
    listen 80;
    server_name example.com;

    # 静的ファイル
    location /static/ {
        root /var/www/html;
        expires 30d;
    }

    # API
    location /api/ {
        proxy_pass http://127.0.0.1:3000;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    }

    # その他のリクエスト
    location / {
        proxy_pass http://127.0.0.1:8080;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    }
}
```

### 8. パス書き換え

```nginx
location /app/ {
    proxy_pass http://127.0.0.1:3000/;
    proxy_set_header Host $host;
    proxy_set_header X-Real-IP $remote_addr;
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;

    # パスの書き換え
    rewrite ^/app/(.*)$ /$1 break;
}
```

## 設定のベストプラクティス

### 9. セキュリティ設定

```nginx
server {
    listen 80;
    server_name example.com;

    location / {
        proxy_pass http://127.0.0.1:3000;

        # セキュリティヘッダー
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;

        # 内部ヘッダーの削除
        proxy_hide_header X-Powered-By;

        # レスポンスヘッダーの追加
        add_header X-Frame-Options "SAMEORIGIN" always;
        add_header X-Content-Type-Options "nosniff" always;
    }
}
```

### 10. ログ設定

```nginx
http {
    log_format proxy '$remote_addr - $remote_user [$time_local] '
                    '"$request" $status $body_bytes_sent '
                    '"$http_referer" "$http_user_agent" '
                    'rt=$request_time uct="$upstream_connect_time" '
                    'uht="$upstream_header_time" urt="$upstream_response_time"';

    server {
        listen 80;
        server_name example.com;

        access_log /var/log/nginx/proxy.log proxy;

        location / {
            proxy_pass http://127.0.0.1:3000;
            # ... その他の設定
        }
    }
}
```

これらの設定を参考に、あなたの具体的な要件に合わせてカスタマイズしてください。設定後は必ず `nginx -t` でテストし、問題がなければ `nginx -s reload` で設定を反映させてください。

何か特定のケースや詳細について質問があれば、お気軽にお聞きください！

Nginxのリバースプロキシ設定について説明します。

## 基本的なリバースプロキシ設定

### 1. 基本構文

```nginx
server {
    listen 80;
    server_name example.com;

    location / {
        proxy_pass http://backend_server;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }
}
```

### 2. よく使用されるproxy設定

```nginx
server {
    listen 80;
    server_name myapp.com;

    location / {
        # バックエンドサーバーの指定
        proxy_pass http://127.0.0.1:3000;

        # ヘッダーの設定
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;

        # タイムアウト設定
        proxy_connect_timeout 60s;
        proxy_send_timeout 60s;
        proxy_read_timeout 60s;

        # バッファリング設定
        proxy_buffering on;
        proxy_buffer_size 4k;
        proxy_buffers 8 4k;
    }
}
```

## アップストリーム設定（負荷分散）

```nginx
# アップストリームの定義
upstream backend {
    server 127.0.0.1:3000;
    server 127.0.0.1:3001;
    server 127.0.0.1:3002;
}

server {
    listen 80;
    server_name example.com;

    location / {
        proxy_pass http://backend;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    }
}
```

## 高度な設定例

### 1. SSL終端とHTTPSリダイレクト

```nginx
# HTTP to HTTPS redirect
server {
    listen 80;
    server_name example.com;
    return 301 https://$server_name$request_uri;
}

# HTTPS server
server {
    listen 443 ssl;
    server_name example.com;

    ssl_certificate /path/to/certificate.crt;
    ssl_certificate_key /path/to/private.key;

    location / {
        proxy_pass http://127.0.0.1:3000;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto https;
        proxy_set_header X-Forwarded-Ssl on;
    }
}
```

### 2. パス別のルーティング

```nginx
server {
    listen 80;
    server_name example.com;

    # API requests
    location /api/ {
        proxy_pass http://127.0.0.1:3000/;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    }

    # Static files
    location /static/ {
        proxy_pass http://127.0.0.1:8080/;
    }

    # Default frontend
    location / {
        proxy_pass http://127.0.0.1:3001;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    }
}
```

### 3. WebSocket対応

```nginx
server {
    listen 80;
    server_name example.com;

    location /ws/ {
        proxy_pass http://127.0.0.1:3000;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_read_timeout 86400;
    }
}
```

## 重要なproxy設定パラメータ

| パラメータ | 説明 | 例 |
|-----------|------|-----|
| `proxy_pass` | バックエンドサーバーのURL | `http://127.0.0.1:3000` |
| `proxy_set_header` | ヘッダーの設定 | `Host $host` |
| `proxy_connect_timeout` | 接続タイムアウト | `60s` |
| `proxy_read_timeout` | 読み取りタイムアウト | `60s` |
| `proxy_send_timeout` | 送信タイムアウト | `60s` |
| `proxy_buffering` | バッファリングの有効/無効 | `on/off` |
| `proxy_redirect` | リダイレクトの書き換え | `default` |

## トラブルシューティング

### ログ設定

```nginx
error_log /var/log/nginx/error.log debug;
access_log /var/log/nginx/access.log;
```

### よくある問題と解決方法

1. **502 Bad Gateway**: バックエンドサーバーが起動していない
2. **504 Gateway Timeout**: タイムアウト値を調整
3. **Real IPが取得できない**: `X-Real-IP`ヘッダーの設定を確認

この設定を参考に、あなたの環境に合わせてカスタマイズしてください。何か具体的な質問があれば、お気軽にお聞かせください。

Nginxのリバースプロキシ設定について詳しく説明します。

## 基本的なリバースプロキシ設定

### 1. 基本構文

```nginx
server {
    listen 80;
    server_name example.com;

    location / {
        proxy_pass http://backend-server;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }
}
```

### 2. よく使用されるプロキシディレクティブ

```nginx
location / {
    # バックエンドサーバーの指定
    proxy_pass http://127.0.0.1:8000;

    # タイムアウト設定
    proxy_connect_timeout 30s;
    proxy_send_timeout 30s;
    proxy_read_timeout 30s;

    # バッファリング設定
    proxy_buffering on;
    proxy_buffer_size 4k;
    proxy_buffers 8 4k;

    # キャッシュ制御
    proxy_cache_bypass $http_upgrade;
    proxy_no_cache $http_upgrade;
}
```

## 高度な設定例

### 3. ロードバランシング

```nginx
upstream backend {
    server 192.168.1.10:8000 weight=3;
    server 192.168.1.11:8000 weight=2;
    server 192.168.1.12:8000 backup;
}

server {
    listen 80;
    server_name example.com;

    location / {
        proxy_pass http://backend;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
    }
}
```

### 4. SSL終端（HTTPS対応）

```nginx
server {
    listen 443 ssl http2;
    server_name example.com;

    ssl_certificate /path/to/certificate.crt;
    ssl_certificate_key /path/to/private.key;

    location / {
        proxy_pass http://backend-server;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto https;
    }
}

# HTTP to HTTPS リダイレクト
server {
    listen 80;
    server_name example.com;
    return 301 https://$server_name$request_uri;
}
```

### 5. WebSocket対応

```nginx
location /websocket {
    proxy_pass http://backend-websocket;
    proxy_http_version 1.1;
    proxy_set_header Upgrade $http_upgrade;
    proxy_set_header Connection "upgrade";
    proxy_set_header Host $host;
    proxy_cache_bypass $http_upgrade;
}
```

### 6. API別ルーティング

```nginx
server {
    listen 80;
    server_name api.example.com;

    # API v1
    location /v1/ {
        proxy_pass http://api-v1-backend/;
        include /etc/nginx/proxy_params;
    }

    # API v2
    location /v2/ {
        proxy_pass http://api-v2-backend/;
        include /etc/nginx/proxy_params;
    }

    # 静的ファイル
    location /static/ {
        root /var/www/static;
        expires 30d;
    }
}
```

### 7. プロキシパラメータファイル（/etc/nginx/proxy_params）

```nginx
proxy_set_header Host $http_host;
proxy_set_header X-Real-IP $remote_addr;
proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
proxy_set_header X-Forwarded-Proto $scheme;
proxy_connect_timeout 30;
proxy_send_timeout 30;
proxy_read_timeout 30;
```

## パフォーマンス最適化

### 8. キャッシュ設定

```nginx
proxy_cache_path /var/cache/nginx levels=1:2 keys_zone=my_cache:10m max_size=10g 
                 inactive=60m use_temp_path=off;

server {
    location / {
        proxy_cache my_cache;
        proxy_cache_revalidate on;
        proxy_cache_min_uses 3;
        proxy_cache_use_stale error timeout updating http_500 http_502 http_503 http_504;
        proxy_cache_background_update on;
        proxy_cache_lock on;

        proxy_pass http://backend;
    }
}
```

### 9. 圧縮設定

```nginx
gzip on;
gzip_vary on;
gzip_min_length 1024;
gzip_types text/plain text/css text/xml text/javascript 
           application/javascript application/xml+rss application/json;
```

## セキュリティ強化

### 10. セキュリティヘッダー

```nginx
server {
    # セキュリティヘッダー追加
    add_header X-Frame-Options "SAMEORIGIN" always;
    add_header X-Content-Type-Options "nosniff" always;
    add_header X-XSS-Protection "1; mode=block" always;
    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains" always;

    location / {
        proxy_pass http://backend;
        proxy_hide_header X-Powered-By;
        include /etc/nginx/proxy_params;
    }
}
```

この設定を参考に、あなたの環境に合わせてカスタマイズしてください。何か特定の用途や疑問があれば、お気軽にお聞かせください。

