Node.jsアプリのメモリリークを調査する方法について、段階的にご説明します。

## 1. 基本的な監視方法

### メモリ使用量の確認
```javascript
// メモリ使用量を定期的に出力
setInterval(() => {
  const memUsage = process.memoryUsage();
  console.log({
    rss: `${Math.round(memUsage.rss / 1024 / 1024)} MB`, // 物理メモリ
    heapTotal: `${Math.round(memUsage.heapTotal / 1024 / 1024)} MB`,
    heapUsed: `${Math.round(memUsage.heapUsed / 1024 / 1024)} MB`,
    external: `${Math.round(memUsage.external / 1024 / 1024)} MB`
  });
}, 5000);
```

## 2. プロファイリングツールの活用

### Node.js組み込みのInspector
```bash
# アプリを起動（inspectorモードで）
node --inspect=0.0.0.0:9229 app.js

# Chrome DevToolsでプロファイリング
# chrome://inspect でアクセス
```

### Clinic.jsを使用
```bash
# インストール
npm install -g clinic

# メモリリーク検出
clinic doctor -- node app.js
clinic bubbleprof -- node app.js
```

## 3. ヒープダンプの取得と分析

### ヒープダンプの生成
```javascript
const v8 = require('v8');
const fs = require('fs');

// ヒープスナップショットを取得
function takeHeapSnapshot() {
  const snapshot = v8.writeHeapSnapshot();
  console.log('Heap snapshot written to', snapshot);
  return snapshot;
}

// 定期的にヒープダンプを取得
setInterval(takeHeapSnapshot, 60000);
```

### 手動でヒープダンプを取得
```bash
# プロセスIDを取得
ps aux | grep node

# ヒープダンプを生成
kill -USR2 <process_id>
```

## 4. 一般的なメモリリークパターンの検出

### イベントリスナーの監視
```javascript
// EventEmitterの監視
process.on('warning', (warning) => {
  if (warning.name === 'MaxListenersExceededWarning') {
    console.log('Memory leak suspected: Too many listeners');
    console.log(warning);
  }
});

// リスナー数の確認
function checkListeners(emitter, eventName) {
  const count = emitter.listenerCount(eventName);
  if (count > 10) { // 閾値は適切に設定
    console.warn(`High listener count for ${eventName}: ${count}`);
  }
}
```

### タイマーとコールバックの監視
```javascript
// アクティブなハンドルの数を監視
setInterval(() => {
  console.log('Active handles:', process._getActiveHandles().length);
  console.log('Active requests:', process._getActiveRequests().length);
}, 10000);
```

## 5. 実用的な監視コード例

```javascript
class MemoryMonitor {
  constructor() {
    this.startTime = Date.now();
    this.samples = [];
  }

  start() {
    setInterval(() => {
      this.sample();
    }, 5000);

    // プロセス終了時にレポート生成
    process.on('SIGINT', () => {
      this.generateReport();
      process.exit(0);
    });
  }

  sample() {
    const mem = process.memoryUsage();
    const sample = {
      timestamp: Date.now(),
      rss: mem.rss,
      heapTotal: mem.heapTotal,
      heapUsed: mem.heapUsed,
      external: mem.external
    };

    this.samples.push(sample);

    // メモリリークの兆候をチェック
    this.checkForLeaks(sample);
  }

  checkForLeaks(current) {
    if (this.samples.length < 10) return;

    const recent = this.samples.slice(-10);
    const trend = this.calculateTrend(recent, 'heapUsed');

    if (trend > 1024 * 1024) { // 1MB/sample の増加傾向
      console.warn('⚠️  Memory leak detected! Heap usage trending upward');
      this.takeHeapSnapshot();
    }
  }

  calculateTrend(samples, property) {
    const values = samples.map(s => s[property]);
    const n = values.length;
    const sumX = (n * (n - 1)) / 2;
    const sumY = values.reduce((a, b) => a + b);
    const sumXY = values.reduce((sum, y, x) => sum + x * y, 0);
    const sumXX = values.reduce((sum, _, x) => sum + x * x, 0);

    return (n * sumXY - sumX * sumY) / (n * sumXX - sumX * sumX);
  }

  takeHeapSnapshot() {
    if (typeof v8 !== 'undefined') {
      const snapshot = v8.writeHeapSnapshot();
      console.log('📊 Heap snapshot saved:', snapshot);
    }
  }

  generateReport() {
    const duration = (Date.now() - this.startTime) / 1000;
    const latest = this.samples[this.samples.length - 1];

    console.log('\n📋 Memory Usage Report:');
    console.log(`Duration: ${duration}s`);
    console.log(`Final RSS: ${(latest.rss / 1024 / 1024).toFixed(2)} MB`);
    console.log(`Final Heap: ${(latest.heapUsed / 1024 / 1024).toFixed(2)} MB`);
  }
}

// 使用例
const monitor = new MemoryMonitor();
monitor.start();
```

## 6. 外部ツールの活用

### pm2を使用した監視
```bash
# pm2でアプリを起動
pm2 start app.js --name myapp

# メモリ監視
pm2 monit

# ログでメモリ使用量を確認
pm2 logs
```

## 7. 予防策とベストプラクティス

```javascript
// リスナーの適切なクリーンアップ
class ResourceManager {
  constructor() {
    this.resources = [];
  }

  addResource(resource) {
    this.resources.push(resource);
  }

  cleanup() {
    this.resources.forEach(resource => {
      if (resource.removeAllListeners) {
        resource.removeAllListeners();
      }
      if (resource.close) {
        resource.close();
      }
    });
    this.resources = [];
  }
}

// プロセス終了時のクリーンアップ
process.on('SIGINT', cleanup);
process.on('SIGTERM', cleanup);

function cleanup() {
  console.log('Cleaning up resources...');
  // リソースのクリーンアップ処理
  process.exit(0);
}
```

これらの方法を組み合わせることで、Node.jsアプリのメモリリークを効果的に調査・特定できます。まずは基本的な監視から始めて、必要に応じてより詳細な分析ツールを使用することをお勧めします。

Node.jsアプリのメモリリークを調査する方法について、段階的にご説明します。

## 1. メモリリークの兆候を確認

まず、以下の症状がないか確認しましょう：

```javascript
// プロセス情報を定期的にチェック
setInterval(() => {
    const used = process.memoryUsage();
    console.log('Memory Usage:', {
        rss: Math.round(used.rss / 1024 / 1024 * 100) / 100 + ' MB',
        heapTotal: Math.round(used.heapTotal / 1024 / 1024 * 100) / 100 + ' MB',
        heapUsed: Math.round(used.heapUsed / 1024 / 1024 * 100) / 100 + ' MB'
    });
}, 10000);
```

## 2. 基本的なツールを使った調査

### Node.js内蔵のツール

```javascript
// ヒープダンプの生成
const v8 = require('v8');
const fs = require('fs');

function generateHeapDump() {
    const heapSnapshot = v8.writeHeapSnapshot();
    console.log('Heap snapshot written to:', heapSnapshot);
}
```

### プロファイリングツールの利用

```bash
# Node.jsのインスペクタを使用
node --inspect --inspect-brk your-app.js

# Chrome DevToolsでプロファイリング
# chrome://inspect でアクセス
```

## 3. サードパーティツールの活用

### clinic.js を使用

```bash
npm install -g clinic
clinic doctor -- node your-app.js
clinic bubbleprof -- node your-app.js
```

### heapdumpパッケージ

```javascript
const heapdump = require('heapdump');

// SIGUSRシグナルでヒープダンプを生成
process.on('SIGUSR2', () => {
    heapdump.writeSnapshot((err, filename) => {
        console.log('Heap dump written to', filename);
    });
});
```

## 4. よくあるメモリリークパターンと対策

### イベントリスナーの削除忘れ

```javascript
// 問題のあるコード
const EventEmitter = require('events');
const emitter = new EventEmitter();

function badFunction() {
    emitter.on('event', () => {
        // 処理...
    });
    // リスナーが削除されない
}

// 修正版
function goodFunction() {
    const listener = () => {
        // 処理...
    };
    emitter.on('event', listener);

    // 適切なタイミングでリスナーを削除
    setTimeout(() => {
        emitter.removeListener('event', listener);
    }, 1000);
}
```

### タイマーのクリアし忘れ

```javascript
// 問題のあるコード
function badTimer() {
    const interval = setInterval(() => {
        // 処理...
    }, 1000);
    // clearIntervalが呼ばれない
}

// 修正版
function goodTimer() {
    const interval = setInterval(() => {
        // 処理...
    }, 1000);

    // 適切にクリア
    setTimeout(() => {
        clearInterval(interval);
    }, 10000);
}
```

### グローバル変数への参照蓄積

```javascript
// 問題のあるコード
global.cache = [];

function badCache(data) {
    global.cache.push(data); // 際限なく蓄積
}

// 修正版
const cache = new Map();

function goodCache(key, data) {
    // サイズ制限付きキャッシュ
    if (cache.size > 1000) {
        const firstKey = cache.keys().next().value;
        cache.delete(firstKey);
    }
    cache.set(key, data);
}
```

## 5. 監視とアラートの設定

### メモリ監視の実装

```javascript
const os = require('os');

class MemoryMonitor {
    constructor(threshold = 0.8) {
        this.threshold = threshold;
        this.monitoring = false;
    }

    start() {
        if (this.monitoring) return;
        this.monitoring = true;

        this.interval = setInterval(() => {
            const used = process.memoryUsage();
            const total = os.totalmem();
            const usage = used.rss / total;

            if (usage > this.threshold) {
                console.warn(`Memory usage high: ${Math.round(usage * 100)}%`);
                this.generateHeapDump();
            }
        }, 30000);
    }

    stop() {
        if (this.interval) {
            clearInterval(this.interval);
            this.monitoring = false;
        }
    }

    generateHeapDump() {
        const v8 = require('v8');
        const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
        const filename = `heapdump-${timestamp}.heapsnapshot`;

        v8.writeHeapSnapshot(filename);
        console.log(`Heap dump created: ${filename}`);
    }
}

// 使用例
const monitor = new MemoryMonitor(0.8);
monitor.start();
```

## 6. 実践的なデバッグ手順

1. **症状の確認**: メモリ使用量が継続的に増加するか確認
2. **ヒープダンプの取得**: 時間を空けて複数回取得
3. **Chrome DevToolsで分析**: ヒープダンプを比較
4. **疑わしい箇所の特定**: Retainer情報を確認
5. **コード修正**: 特定した問題箇所を修正
6. **検証**: 修正後の動作を確認

この手順を実践することで、効果的にメモリリークを特定し、解決することができます。特に Chrome DevTools の Memory タブは非常に強力なツールなので、ぜひ活用してください。

Node.jsアプリでメモリリークを調査する方法について、段階的に説明いたします。

## 1. メモリ使用量の監視

### 基本的な監視
```javascript
// メモリ使用量をログ出力
function logMemoryUsage() {
  const usage = process.memoryUsage();
  console.log({
    rss: `${Math.round(usage.rss / 1024 / 1024)} MB`,      // 実メモリ使用量
    heapTotal: `${Math.round(usage.heapTotal / 1024 / 1024)} MB`,
    heapUsed: `${Math.round(usage.heapUsed / 1024 / 1024)} MB`,
    external: `${Math.round(usage.external / 1024 / 1024)} MB`
  });
}

// 定期的に監視
setInterval(logMemoryUsage, 5000);
```

### ヒープダンプの生成
```javascript
const v8 = require('v8');
const fs = require('fs');

function generateHeapDump() {
  const heapSnapshot = v8.writeHeapSnapshot();
  console.log('ヒープダンプを生成しました:', heapSnapshot);
}

// 必要な時点でダンプを生成
generateHeapDump();
```

## 2. 開発者ツールを使った分析

### Chrome DevToolsでの分析
```bash
# --inspectフラグでアプリを起動
node --inspect=0.0.0.0:9229 app.js

# またはブレークポイントで停止
node --inspect-brk=0.0.0.0:9229 app.js
```

1. Chrome で `chrome://inspect` にアクセス
2. 対象のプロセスを選択
3. Memory タブでヒープスナップショットを取得
4. 時系列で比較して増加している要素を特定

## 3. 専用ツールの使用

### clinic.js
```bash
npm install -g @nearform/clinic

# メモリリークを検出
clinic doctor -- node app.js
clinic flame -- node app.js
clinic bubbleprof -- node app.js
```

### heapdump
```javascript
const heapdump = require('heapdump');

// SIGUSRシグナルでヒープダンプを生成
process.on('SIGUSR2', () => {
  heapdump.writeSnapshot((err, filename) => {
    if (err) console.error(err);
    else console.log('ヒープダンプ:', filename);
  });
});
```

## 4. よくあるメモリリークのパターンと対策

### グローバル変数
```javascript
// ❌ 悪い例
global.cache = {};
global.cache[key] = largeObject;

// ✅ 良い例
const cache = new Map();
// WeakMapやLRUキャッシュの使用を検討
```

### イベントリスナーの削除漏れ
```javascript
// ❌ 悪い例
emitter.on('data', handler);

// ✅ 良い例
emitter.on('data', handler);
// 使用後は必ず削除
emitter.removeListener('data', handler);
// またはonce()を使用
emitter.once('data', handler);
```

### タイマーの停止漏れ
```javascript
// ❌ 悪い例
setInterval(() => {
  // 処理
}, 1000);

// ✅ 良い例
const intervalId = setInterval(() => {
  // 処理
}, 1000);

// 適切なタイミングで停止
clearInterval(intervalId);
```

### ストリームのリークチェック
```javascript
const stream = require('stream');

class MonitoredStream extends stream.Readable {
  constructor(options) {
    super(options);
    this.on('pipe', () => {
      console.log('Stream piped');
    });
    this.on('unpipe', () => {
      console.log('Stream unpiped');
    });
  }
}
```

## 5. 継続的な監視

### アプリケーション内監視
```javascript
class MemoryMonitor {
  constructor() {
    this.baseline = process.memoryUsage();
    this.alerts = [];
  }

  check() {
    const current = process.memoryUsage();
    const heapGrowth = current.heapUsed - this.baseline.heapUsed;

    if (heapGrowth > 100 * 1024 * 1024) { // 100MB以上増加
      console.warn('メモリ使用量が異常に増加しています');
      this.generateReport();
    }
  }

  generateReport() {
    // ヒープダンプの生成やアラート送信
  }
}

const monitor = new MemoryMonitor();
setInterval(() => monitor.check(), 30000);
```

## 6. プロファイリングのベストプラクティス

### 本番環境での注意点
```javascript
// 本番環境では軽量な監視のみ
if (process.env.NODE_ENV === 'production') {
  // 基本的なメトリクス収集のみ
  setInterval(() => {
    const usage = process.memoryUsage();
    // ログ出力やメトリクス送信
  }, 60000);
} else {
  // 開発環境では詳細な分析
  require('./detailed-profiling');
}
```

これらの方法を組み合わせることで、効果的にメモリリークを特定し、対策を講じることができます。まずは基本的な監視から始めて、異常を検知したら詳細な分析を行うのが効率的です。

caveman_texts:
Node.js メモリリーク調査方法:

## 基本監視

**process.memoryUsage()** で現在使用量確認:
```javascript
setInterval(() => {
  const mem = process.memoryUsage();
  console.log(`RSS: ${mem.rss / 1024 / 1024}MB`);
  console.log(`Heap: ${mem.heapUsed / 1024 / 1024}MB`);
}, 5000);
```

**--max-old-space-size** でヒープサイズ制限。リーク時早期クラッシュさせる:
```bash
node --max-old-space-size=512 app.js
```

## プロファイリングツール

**heapdump** でヒープスナップショット取得:
```javascript
const heapdump = require('heapdump');
// 手動
heapdump.writeSnapshot('./heap-' + Date.now() + '.heapsnapshot');
```

**Chrome DevTools** でスナップショット解析。Large objects見つける。

**clinic.js** でリアルタイム監視:
```bash
npm install -g clinic
clinic doctor -- node app.js
```

## 一般的リーク原因

**イベントリスナー削除忘れ**:
```javascript
// 悪い例
emitter.on('data', handler);

// 良い例  
emitter.on('data', handler);
process.on('exit', () => emitter.removeListener('data', handler));
```

**グローバル変数蓄積**:
```javascript
// 悪い例
global.cache = global.cache || {};
global.cache[key] = data; // 削除されない

// 良い例
const cache = new Map();
cache.set(key, data);
cache.delete(key); // 明示的削除
```

**タイマー削除忘れ**:
```javascript
const timer = setInterval(() => {}, 1000);
// clearInterval(timer) 忘れ
```

**クロージャで大きオブジェクト保持**:
```javascript
function createHandler(largeData) {
  return function() {
    // largeData参照なくても保持される
    console.log('handled');
  };
}
```

## 調査パターン

1. **メモリ使用量グラフ化** → 増加傾向確認
2. **負荷テスト** → リーク再現
3. **ヒープスナップショット比較** → 増加オブジェクト特定
4. **コード該当箇所修正**
5. **再テスト** → 修正確認

WeakMap/WeakSet使えば自動GC。参照切れたら削除される。

Node.jsメモリリーク調査方法：

## 基本監視

**プロセス監視**
```bash
# メモリ使用量チェック
node --max-old-space-size=512 app.js
top -p $(pgrep node)
```

**内蔵監視**
```javascript
// ヒープ使用量
console.log(process.memoryUsage());
// { rss, heapTotal, heapUsed, external }

// 定期監視
setInterval(() => {
  const mem = process.memoryUsage();
  console.log(`Heap: ${mem.heapUsed / 1024 / 1024}MB`);
}, 5000);
```

## プロファイリングツール

**Chrome DevTools**
```bash
node --inspect app.js
# chrome://inspect でヒープスナップショット
```

**clinic.js**
```bash
npm install -g clinic
clinic doctor -- node app.js
clinic bubbleprof -- node app.js
```

**heapdump**
```javascript
const heapdump = require('heapdump');
// メモリ急増時
heapdump.writeSnapshot((err, filename) => {
  console.log(`Snapshot: ${filename}`);
});
```

## 一般的リーク原因

**グローバル変数蓄積**
```javascript
// ダメ
let cache = {};
function addToCache(key, data) {
  cache[key] = data; // 無限蓄積
}

// 良い
const cache = new Map();
const MAX_SIZE = 1000;
function addToCache(key, data) {
  if (cache.size >= MAX_SIZE) {
    const firstKey = cache.keys().next().value;
    cache.delete(firstKey);
  }
  cache.set(key, data);
}
```

**イベントリスナー未削除**
```javascript
// ダメ
function setupHandler(element) {
  element.on('click', handler);
  // removeListener忘れ
}

// 良い
function cleanup() {
  element.removeListener('click', handler);
}
```

**クロージャー参照**
```javascript
// ダメ - 大きなオブジェクト保持
function createHandler(bigData) {
  return function() {
    console.log('handled');
    // bigData参照残る
  };
}

// 良い
function createHandler() {
  return function() {
    console.log('handled');
  };
}
```

## 調査手順

1. **ベースライン取得** - 正常時メモリ使用量
2. **負荷テスト** - リクエスト増加でメモリ推移確認
3. **ヒープ比較** - スナップショット差分分析
4. **コード特定** - リーク箇所絞り込み
5. **修正検証** - 再テストで改善確認

**--max-old-space-size**でメモリ制限設定。限界近づくとGC頻発→性能劣化で早期発見可能。

Node.jsメモリリーク調査手順:

## 症状確認
```bash
# プロセスメモリ監視
ps aux | grep node
# RSS増加続く = リーク疑い
```

## 調査ツール

**heapdump**
```bash
npm install heapdump
```
```js
// アプリに追加
const heapdump = require('heapdump');
// /kill -USR2 <pid> でダンプ取得
```

**clinic.js**
```bash
npm install -g clinic
clinic doctor -- node app.js
clinic bubbleprof -- node app.js
```

**--inspect使用**
```bash
node --inspect app.js
# Chrome DevTools → Memory → Heap Snapshot
```

## 主要原因

**イベントリスナー削除忘れ**
```js
// NG
setInterval(() => {}, 1000); // clearInterval忘れ
emitter.on('event', handler); // removeListener忘れ

// OK  
const timer = setInterval(() => {}, 1000);
clearInterval(timer);
```

**クロージャー内大容量データ**
```js
// NG - bigDataが解放されない
function process() {
  const bigData = Buffer.alloc(10000000);
  return () => console.log('done'); // bigData参照残る
}

// OK
function process() {
  const bigData = Buffer.alloc(10000000);
  // 処理後
  bigData = null; // 明示的null化
  return () => console.log('done');
}
```

**グローバル変数蓄積**
```js
// NG
global.cache = global.cache || {};
global.cache[key] = data; // 無制限蓄積

// OK - LRU使用
const LRU = require('lru-cache');
const cache = new LRU({ max: 500 });
```

## 監視コード
```js
// メモリ使用量ログ
setInterval(() => {
  const mem = process.memoryUsage();
  console.log({
    rss: Math.round(mem.rss / 1024 / 1024) + 'MB',
    heapUsed: Math.round(mem.heapUsed / 1024 / 1024) + 'MB'
  });
}, 10000);
```

定期ダンプ取得 → Chrome DevToolsで比較 → 増加オブジェクト特定 → コード修正。

N+1クエリ問題 = 1回で取得できるデータを N+1回のクエリで取得してしまう問題。

**問題例:**
```javascript
// 悪い例 - N+1クエリ
const users = await User.findAll(); // 1回目のクエリ
for (const user of users) {
  const posts = await Post.findAll({ userId: user.id }); // N回のクエリ
}
```

ユーザー100人いたら101回クエリ実行。遅い。

**解決方法:**

1. **Eager Loading (一括取得)**
```javascript
// Sequelize例
const users = await User.findAll({
  include: [{ model: Post }] // JOIN使って1回で取得
});
```

2. **バッチクエリ**
```javascript
const users = await User.findAll();
const userIds = users.map(u => u.id);
const posts = await Post.findAll({ 
  where: { userId: userIds } // IN句で一括取得
});
```

3. **DataLoader使用**
```javascript
const postLoader = new DataLoader(async (userIds) => {
  const posts = await Post.findAll({ where: { userId: userIds } });
  return userIds.map(id => posts.filter(p => p.userId === id));
});
```

核心 = 複数回クエリを1回にまとめる。

N+1問題：1クエリでデータ取得、各行でN回追加クエリ実行。例：ユーザー100人取得→各ユーザーの投稿取得で100回クエリ。計101回DB叩く。

## 原因
```javascript
// 悪い例 - N+1発生
users = await User.findAll()  // 1回目
for (user of users) {
  posts = await Post.findAll({userId: user.id})  // N回
}
```

## 解決法

**1. Eager Loading（一括取得）**
```javascript
// Sequelize
users = await User.findAll({
  include: [Post]  // JOIN使用、1クエリで全データ
})

// Prisma  
users = await prisma.user.findMany({
  include: { posts: true }
})
```

**2. データローダー**
```javascript
// DataLoader使用
const postLoader = new DataLoader(async (userIds) => {
  posts = await Post.findAll({userId: {$in: userIds}})
  return userIds.map(id => posts.filter(p => p.userId === id))
})
```

**3. バッチクエリ**
```sql
-- 手動バッチ
SELECT * FROM users;
SELECT * FROM posts WHERE user_id IN (1,2,3...);
```

GraphQL特に注意。リゾルバー各フィールドで発生しやすい。DataLoader必須。

