Pythonのデコレータについて詳しく説明させていただきます。

## デコレータとは

デコレータは、既存の関数やクラスの動作を変更したり拡張したりするための仕組みです。元の関数を直接変更することなく、追加の機能を付け加えることができます。

## 基本的な仕組み

### 1. 関数は第一級オブジェクト

Pythonでは関数も他の値と同じようにオブジェクトとして扱えます：

```python
def greet():
    return "Hello!"

# 関数を変数に代入
func = greet
print(func())  # "Hello!"

# 関数を引数として渡す
def call_function(f):
    return f()

print(call_function(greet))  # "Hello!"
```

### 2. 高階関数（関数を返す関数）

```python
def create_multiplier(x):
    def multiplier(y):
        return x * y
    return multiplier

double = create_multiplier(2)
print(double(5))  # 10
```

## デコレータの基本形

### 手動でのデコレート

```python
def my_decorator(func):
    def wrapper():
        print("関数の実行前")
        result = func()
        print("関数の実行後")
        return result
    return wrapper

def say_hello():
    print("Hello!")

# 手動でデコレート
decorated_hello = my_decorator(say_hello)
decorated_hello()
```

### @記法を使ったデコレート

```python
def my_decorator(func):
    def wrapper():
        print("関数の実行前")
        result = func()
        print("関数の実行後")
        return result
    return wrapper

@my_decorator
def say_hello():
    print("Hello!")

say_hello()  # デコレートされた状態で実行
```

## 引数を受け取る関数のデコレート

```python
def my_decorator(func):
    def wrapper(*args, **kwargs):
        print(f"関数 {func.__name__} を実行します")
        result = func(*args, **kwargs)
        print("実行完了")
        return result
    return wrapper

@my_decorator
def add(a, b):
    return a + b

print(add(3, 5))  # 8
```

## 実用的なデコレータの例

### 1. 実行時間測定デコレータ

```python
import time
from functools import wraps

def measure_time(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        start = time.time()
        result = func(*args, **kwargs)
        end = time.time()
        print(f"{func.__name__} の実行時間: {end - start:.4f}秒")
        return result
    return wrapper

@measure_time
def slow_function():
    time.sleep(1)
    return "完了"

slow_function()
```

### 2. キャッシュデコレータ

```python
def cache(func):
    cached_results = {}

    @wraps(func)
    def wrapper(*args):
        if args in cached_results:
            print(f"キャッシュから取得: {args}")
            return cached_results[args]

        result = func(*args)
        cached_results[args] = result
        return result

    return wrapper

@cache
def fibonacci(n):
    if n < 2:
        return n
    return fibonacci(n - 1) + fibonacci(n - 2)

print(fibonacci(10))  # 計算結果がキャッシュされる
```

## パラメータ付きデコレータ

```python
def repeat(times):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for _ in range(times):
                result = func(*args, **kwargs)
            return result
        return wrapper
    return decorator

@repeat(3)
def greet(name):
    print(f"Hello, {name}!")

greet("太郎")  # 3回実行される
```

## クラスベースのデコレータ

```python
class CountCalls:
    def __init__(self, func):
        self.func = func
        self.count = 0

    def __call__(self, *args, **kwargs):
        self.count += 1
        print(f"{self.func.__name__} が {self.count} 回目の実行")
        return self.func(*args, **kwargs)

@CountCalls
def say_hello():
    print("Hello!")

say_hello()  # 1回目
say_hello()  # 2回目
```

## 複数のデコレータ

```python
def bold(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        result = func(*args, **kwargs)
        return f"<b>{result}</b>"
    return wrapper

def italic(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        result = func(*args, **kwargs)
        return f"<i>{result}</i>"
    return wrapper

@bold
@italic
def get_text():
    return "Hello World"

print(get_text())  # <b><i>Hello World</i></b>
```

## 注意点とベストプラクティス

### functools.wrapsの使用

```python
from functools import wraps

def my_decorator(func):
    @wraps(func)  # 元の関数のメタデータを保持
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper
```

### デバッグ時の考慮事項

```python
import functools

def debug_decorator(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        print(f"関数名: {func.__name__}")
        print(f"引数: args={args}, kwargs={kwargs}")
        result = func(*args, **kwargs)
        print(f"戻り値: {result}")
        return result
    return wrapper
```

デコレータは、ログ記録、認証、キャッシュ、バリデーションなど、横断的な関心事を扱うのに非常に有効な機能です。コードの重複を避け、関心の分離を実現できる強力なツールです。

Pythonのデコレータについて詳しく説明させていただきます。

## デコレータとは

デコレータは、既存の関数やクラスを変更することなく、その動作を拡張・修正できる仕組みです。関数を引数として受け取り、新しい関数を返す高階関数として実装されます。

## 基本的な仕組み

### 1. 関数型デコレータの基本形

```python
def my_decorator(func):
    def wrapper(*args, **kwargs):
        # 元の関数を呼ぶ前の処理
        print(f"{func.__name__}を呼び出します")
        result = func(*args, **kwargs)
        # 元の関数を呼んだ後の処理
        print(f"{func.__name__}の実行が完了しました")
        return result
    return wrapper

# デコレータの使用
@my_decorator
def greet(name):
    print(f"こんにちは、{name}さん！")

# 実行
greet("田中")
```

出力：
```
greetを呼び出します
こんにちは、田中さん！
greetの実行が完了しました
```

### 2. デコレータの内部動作

上記の`@my_decorator`は以下と同等です：

```python
def greet(name):
    print(f"こんにちは、{name}さん！")

greet = my_decorator(greet)  # これが@記法の内部動作
```

## 実用的なデコレータの例

### 1. 実行時間測定デコレータ

```python
import time
import functools

def measure_time(func):
    @functools.wraps(func)  # 元関数のメタデータを保持
    def wrapper(*args, **kwargs):
        start_time = time.time()
        result = func(*args, **kwargs)
        end_time = time.time()
        print(f"{func.__name__}の実行時間: {end_time - start_time:.4f}秒")
        return result
    return wrapper

@measure_time
def slow_function():
    time.sleep(1)
    return "処理完了"

slow_function()
```

### 2. リトライ機能付きデコレータ

```python
import random
import time

def retry(max_attempts=3, delay=1):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(max_attempts):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    if attempt == max_attempts - 1:
                        print(f"最大試行回数({max_attempts})に達しました")
                        raise e
                    print(f"試行 {attempt + 1} 失敗: {e}. {delay}秒後にリトライします...")
                    time.sleep(delay)
        return wrapper
    return decorator

@retry(max_attempts=3, delay=1)
def unreliable_function():
    if random.random() < 0.7:  # 70%の確率で失敗
        raise Exception("ランダムエラー")
    return "成功！"
```

### 3. キャッシュデコレータ

```python
def cache(func):
    cached_results = {}

    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        # 引数をキーとして使用（簡単な例）
        key = str(args) + str(sorted(kwargs.items()))

        if key in cached_results:
            print(f"キャッシュから取得: {key}")
            return cached_results[key]

        result = func(*args, **kwargs)
        cached_results[key] = result
        print(f"結果をキャッシュ: {key}")
        return result

    return wrapper

@cache
def fibonacci(n):
    if n <= 1:
        return n
    return fibonacci(n-1) + fibonacci(n-2)

print(fibonacci(10))  # 初回は計算
print(fibonacci(10))  # 2回目はキャッシュから
```

## パラメータ付きデコレータ

```python
def log_level(level):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            print(f"[{level}] {func.__name__}を実行中...")
            result = func(*args, **kwargs)
            print(f"[{level}] {func.__name__}完了")
            return result
        return wrapper
    return decorator

@log_level("INFO")
def process_data(data):
    return f"データ処理完了: {data}"

@log_level("DEBUG")
def debug_function():
    return "デバッグ情報"
```

## クラスベースのデコレータ

```python
class CountCalls:
    def __init__(self, func):
        self.func = func
        self.count = 0

    def __call__(self, *args, **kwargs):
        self.count += 1
        print(f"{self.func.__name__}が{self.count}回目の呼び出し")
        return self.func(*args, **kwargs)

@CountCalls
def say_hello():
    print("Hello!")

say_hello()  # 1回目
say_hello()  # 2回目
```

## 複数デコレータの適用

```python
@measure_time
@log_level("INFO")
def complex_operation(x, y):
    time.sleep(0.5)
    return x * y

# これは以下と同等:
# complex_operation = measure_time(log_level("INFO")(complex_operation))
```

## 注意点とベストプラクティス

1. **functools.wrapsの使用**: 元の関数のメタデータを保持するため
2. **`*args, **kwargs`の使用**: 任意の引数に対応するため
3. **デコレータの順序**: 複数適用時は内側から外側へ適用される

デコレータは、ログ記録、認証、キャッシュ、性能測定などの横断的関心事を分離するのに非常に有効な仕組みです。

