APIレート制限実装方法。複数パターンあり。

## Token Bucket

最も一般的。バケツにトークン貯める → リクエスト来たらトークン消費。

```javascript
class TokenBucket {
  constructor(capacity, refillRate) {
    this.capacity = capacity;
    this.tokens = capacity;
    this.refillRate = refillRate;
    this.lastRefill = Date.now();
  }

  consume(tokens = 1) {
    this.refill();
    if (this.tokens >= tokens) {
      this.tokens -= tokens;
      return true;
    }
    return false;
  }

  refill() {
    const now = Date.now();
    const tokensToAdd = Math.floor((now - this.lastRefill) / 1000) * this.refillRate;
    this.tokens = Math.min(this.capacity, this.tokens + tokensToAdd);
    this.lastRefill = now;
  }
}
```

## Sliding Window

時間窓でカウント。Redis使用例：

```javascript
async function checkRateLimit(userId, limit, windowMs) {
  const key = `rate_limit:${userId}`;
  const now = Date.now();
  const windowStart = now - windowMs;

  // 古い記録削除
  await redis.zremrangebyscore(key, 0, windowStart);

  // 現在のカウント取得
  const count = await redis.zcard(key);

  if (count >= limit) {
    return false; // 制限超過
  }

  // 新しいリクエスト記録
  await redis.zadd(key, now, now);
  await redis.expire(key, Math.ceil(windowMs / 1000));

  return true;
}
```

## Express Middleware

```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15分
  max: 100, // 最大100リクエスト
  message: 'レート制限超過',
  standardHeaders: true,
  legacyHeaders: false
});

app.use('/api/', limiter);
```

## 分散環境対応

Redis使用 → 複数サーバー間で制限共有可能。

```javascript
const RedisStore = require('rate-limit-redis');

const limiter = rateLimit({
  store: new RedisStore({
    client: redisClient
  }),
  windowMs: 15 * 60 * 1000,
  max: 100
});
```

## レスポンスヘッダー

標準的なヘッダー返す：

```javascript
res.set({
  'X-RateLimit-Limit': 100,
  'X-RateLimit-Remaining': remaining,
  'X-RateLimit-Reset': resetTime
});
```

## 実装選択

- 簡単 → express-rate-limit
- 柔軟性必要 → Token Bucket自作
- 分散 → Redis + Sliding Window

負荷とユーザー体験のバランス重要。

API レート制限実装方法:

## Token Bucket方式
```javascript
class TokenBucket {
  constructor(capacity, refillRate) {
    this.capacity = capacity;
    this.tokens = capacity;
    this.refillRate = refillRate;
    this.lastRefill = Date.now();
  }

  consume() {
    this.refill();
    if (this.tokens > 0) {
      this.tokens--;
      return true;
    }
    return false;
  }

  refill() {
    const now = Date.now();
    const tokensToAdd = Math.floor((now - this.lastRefill) / 1000 * this.refillRate);
    this.tokens = Math.min(this.capacity, this.tokens + tokensToAdd);
    this.lastRefill = now;
  }
}
```

## Redis実装
```javascript
const rateLimiter = async (userId, limit = 100, window = 3600) => {
  const key = `rate_limit:${userId}`;
  const current = await redis.incr(key);

  if (current === 1) {
    await redis.expire(key, window);
  }

  return current <= limit;
};
```

## Express middleware
```javascript
const rateLimit = (maxRequests, windowMs) => {
  const clients = new Map();

  return (req, res, next) => {
    const clientId = req.ip;
    const now = Date.now();
    const client = clients.get(clientId) || { requests: 0, resetTime: now + windowMs };

    if (now > client.resetTime) {
      client.requests = 0;
      client.resetTime = now + windowMs;
    }

    client.requests++;
    clients.set(clientId, client);

    if (client.requests > maxRequests) {
      return res.status(429).json({ error: 'Too Many Requests' });
    }

    res.set({
      'X-RateLimit-Limit': maxRequests,
      'X-RateLimit-Remaining': maxRequests - client.requests,
      'X-RateLimit-Reset': new Date(client.resetTime)
    });

    next();
  };
};
```

## 選択基準
- **メモリ制限**: Sliding window
- **分散環境**: Redis + Lua script  
- **シンプル**: Fixed window
- **精密制御**: Token bucket

429ステータス + Retry-Afterヘッダ必須。ユーザー別/IP別/API key別で制限粒度調整。

API レート制限実装方法。複数アプローチあり。

## Token Bucket方式

最も一般的。バケツにトークン入れる概念。

```javascript
class TokenBucket {
  constructor(capacity, refillRate) {
    this.capacity = capacity;
    this.tokens = capacity;
    this.refillRate = refillRate; // tokens per second
    this.lastRefill = Date.now();
  }

  consume() {
    this.refill();
    if (this.tokens > 0) {
      this.tokens--;
      return true;
    }
    return false;
  }

  refill() {
    const now = Date.now();
    const elapsed = (now - this.lastRefill) / 1000;
    this.tokens = Math.min(
      this.capacity, 
      this.tokens + elapsed * this.refillRate
    );
    this.lastRefill = now;
  }
}
```

## Redis使用例

分散環境対応。

```javascript
const redis = require('redis');
const client = redis.createClient();

async function rateLimit(userId, limit, window) {
  const key = `rate_limit:${userId}:${Math.floor(Date.now() / window)}`;
  const count = await client.incr(key);

  if (count === 1) {
    await client.expire(key, window / 1000);
  }

  return count <= limit;
}

// 使用例: 1分間に10リクエスト
const allowed = await rateLimit('user123', 10, 60000);
```

## Express middleware

```javascript
function createRateLimit(options) {
  const buckets = new Map();

  return (req, res, next) => {
    const key = req.ip; // or req.user.id

    if (!buckets.has(key)) {
      buckets.set(key, new TokenBucket(options.limit, options.refillRate));
    }

    const bucket = buckets.get(key);

    if (bucket.consume()) {
      next();
    } else {
      res.status(429).json({ error: 'Rate limit exceeded' });
    }
  };
}

// 適用
app.use(createRateLimit({ limit: 100, refillRate: 1 }));
```

## 他手法

- **Fixed Window**: 固定時間窓。簡単だが境界問題あり
- **Sliding Window**: 移動窓。正確だが複雑
- **Leaky Bucket**: 一定速度処理。平滑化効果

選択基準: 要件次第。バースト許可→Token Bucket。平滑処理→Leaky Bucket。

