      this.tokens + elapsed * this.refillRate);
    this.lastRefill = now;
  }
}
```

## Fixed Window
- 時間窓固定（1分間等）
- 窓内リク数カウント
- 制限超過で拒否

## Sliding Window
- 移動時間窓
- より正確な制限
- メモリ使用量多

Redis使用推奨。キー = `user_id:timestamp`。TTL設定で自動削除。

レート制限実装パターン:

## Token Bucket
```javascript
class TokenBucket {
  constructor(capacity, refillRate) {
    this.capacity = capacity;
    this.tokens = capacity;
    this.refillRate = refillRate;
    this.lastRefill = Date.now();
  }

  consume() {
    this.refill();
    if (this.tokens > 0) {
      this.tokens--;
      return true;
    }
    return false;
  }

  refill() {
    const now = Date.now();
    const tokensToAdd = Math.floor((now - this.lastRefill) / 1000 * this.refillRate);
    this.tokens = Math.min(this.capacity, this.tokens + tokensToAdd);
    this.lastRefill = now;
  }
}
```

## Fixed Window
```javascript
const rateLimiter = new Map();

function isAllowed(userId, limit, windowMs) {
  const now = Date.now();
  const windowStart = Math.floor(now / windowMs) * windowMs;
  const key = `${userId}:${windowStart}`;

  const current = rateLimiter.get(key) || 0;
  if (current >= limit) return false;

  rateLimiter.set(key, current + 1);
  return true;
}
```

## Sliding Window
Redis使用:
```javascript
async function slidingWindow(redis, userId, limit, windowMs) {
  const now = Date.now();
  const pipeline = redis.pipeline();

  pipeline.zremrangebyscore(userId, 0, now - windowMs);
  pipeline.zcard(userId);
  pipeline.zadd(userId, now, `${now}-${Math.random()}`);
  pipeline.expire(userId, Math.ceil(windowMs / 1000));

  const results = await pipeline.exec();
  const count = results[1][1];

  return count < limit;
}
```

Express middleware:
```javascript
function rateLimit(limiter) {
  return async (req, res, next) => {
    const userId = req.ip;
    const allowed = await limiter.isAllowed(userId);

    if (!allowed) {
      return res.status(429).json({ error: 'Rate limit exceeded' });
    }

    next();
  };
}
```

Token Bucket = バースト許可。Fixed Window = 実装簡単。Sliding = 正確だが重い。
